'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('symposium','Symposium comes from Greek symposion, “drinking together,” from syn- “together” and posis “drinking”; it later named a formal gathering for discussion.',[C('symposium.s1','学术','The university hosted a symposium on how cities can adapt to extreme heat.','大学举办了一场研讨会，讨论城市如何适应极端高温。','hold/host a symposium; symposium on a topic','名词，指专家或学者围绕一个主题进行正式讨论的会议。','participants present and discuss a shared subject.','学术'),C('symposium.s2','出版','The symposium collects essays on ethics by twelve researchers.','这本文集收录了十二位研究者关于伦理学的论文。','a symposium of essays; published symposium','名词，也可指围绕同一主题编成的一组论文。','the book gathers related essays.','出版')],M('The university symposium on heat was a private holiday with no speakers or discussion.','The university symposium brought experts together to discuss urban heat.','symposium是围绕主题讨论的正式会议，不是没有讨论的假期。','meaning'),[Q(1,'A university symposium on urban heat is…','a formal meeting where experts discuss one subject','a small piece of medicine','an informal holiday','Sense 1 is the meeting meaning.','meaning'),Q(2,'A published symposium can be…','a collection of essays on one subject','a gathering with no written work','a city weather station','Sense 2 is the book or essay collection.','context'),Q(1,'Which phrase is natural?','a symposium on climate policy','a symposium for discussing to climate','a symposium of climate policy on','On introduces the topic of a symposium.','collocation'),Q(1,'Greek symposion originally meant…','drinking together','a word with the same meaning','a sign of illness','The historical Greek gathering was a drinking party.','word-formation')]);
P('symptom','Symptom comes through Latin from Greek symptoma, “that which befalls,” from sympiptein, “happen”; it is a bodily sign of illness or evidence of a wider problem.',[C('symptom.s1','医学','A persistent fever can be a symptom of an infection, so she called the clinic.','持续发烧可能是感染的症状，所以她打电话咨询诊所。','a symptom of illness; develop/show symptoms','名词，指表明身体患病的变化或表现。','fever is a physical sign prompting medical advice.','医学'),C('symptom.s2','问题','Repeated delays are a symptom of a deeper staffing problem at the depot.','反复延误是车站更深层人手问题的一个迹象。','a symptom of a problem/crisis; a warning symptom','名词，也指表明存在某个问题的迹象。','delays point to an underlying cause.','问题')],M('The fever was a symptom of infection, although she had no bodily change or sign of illness.','The fever was a possible symptom of infection and prompted a call to the clinic.','症状是疾病的表现，原句否认任何身体表现。','meaning'),[Q(1,'A fever as a symptom is…','a bodily sign that may indicate illness','a complete diagnosis in every case','a formal discussion meeting','Sense 1 is the medical meaning.','meaning'),Q(2,'Repeated delays can be a symptom of…','a deeper staffing problem','a healthy schedule with no issue','a collection of essays','Sense 2 means a sign that a wider problem exists.','context'),Q(1,'Which phrase is natural?','a symptom of flu','a symptom for fluing','a flu symptom ofly','Of introduces the illness indicated.','collocation'),Q(1,'Greek symptoma referred to…','that which befalls or happens','a gathering for drinking','a way of arranging words','The Greek source meant something that happens or befalls someone.','word-formation')]);
P('synagogue','Synagogue comes through Greek synagoge, “assembly,” from syn- “together” and agein “lead”; it is a Jewish place of worship and communal gathering.',C('synagogue.s1','宗教','The neighborhood synagogue opens its doors for worship and community meals.','社区犹太会堂开放礼拜，也举办社区聚餐。','attend/pray at a synagogue; local synagogue','名词，指犹太人礼拜和聚会的场所。','the building serves religious and communal gatherings.','宗教'),M('The Jewish community gathered for worship in a synagogue that was not a building or assembly place.','The Jewish community gathered for worship and assembly in the synagogue.','synagogue指犹太会堂，是礼拜与聚会的场所。','meaning'),[Q(1,'A synagogue is…','a Jewish house of worship and assembly','a laboratory for chromosome pairing','a formal essay collection','That matches the source definition.','meaning'),Q(1,'What takes place at the neighborhood synagogue?','Worship and community gatherings','A particle accelerator experiment only','A language syntax lesson','The context states its religious and communal role.','context'),Q(1,'Which phrase is natural?','worship at a synagogue','worship a synagogue atly','synagogue to worship in at','At identifies the place of worship.','collocation'),Q(1,'The Greek source synagoge meant…','assembly','same-time','cutting off','The word was formed from a Greek term for gathering together.','word-formation')]);
P('synapsis','Synapsis comes from Greek synapsis, “joining,” from syn- “together” and haptein “fasten”; in genetics it is the pairing of homologous chromosomes during meiosis.',C('synapsis.s1','遗传学','During meiosis, synapsis brings homologous chromosomes alongside one another before crossing-over.','减数分裂过程中，同源染色体先通过联会彼此并排，随后发生交叉互换。','chromosomal synapsis; synapsis during meiosis','名词，指减数分裂早期同源染色体配对并排的过程。','homologues pair before genetic exchange.','遗传学'),M('Synapsis during meiosis separates unrelated chromosomes and prevents homologous pairs from coming together.','Synapsis during meiosis pairs homologous chromosomes alongside one another.','synapsis指同源染色体配对，而不是阻止它们靠近。','meaning'),[Q(1,'Synapsis is the…','side-by-side pairing of homologous chromosomes in meiosis','division of a table into rows','fainting from low blood flow','That is the genetics sense.','meaning'),Q(1,'What can synapsis allow?','Crossing-over between paired homologues','The chromosomes to remain unrelated','A meeting to begin at the same time','The paired chromosomes can exchange genetic material.','context'),Q(1,'Which phrase is correct?','synapsis during meiosis','synapsis on mitosisly','the synapsis of to chromosome','During names when the chromosome pairing occurs.','collocation'),Q(1,'Greek synapsis meant…','joining','a summary','a disease pattern','The etymology reflects chromosomes joining in pairs.','word-formation')]);
P('synchronise','Synchronise is the British -ise spelling of synchronize, formed from Greek syn- “together” and chronos “time”; it means make movements or processes match in time.',C('synchronise.s1','动作','The dancers synchronise their steps to the drum so the final turn lands together.','舞者把舞步与鼓点同步，这样最后的转身就能同时完成。','synchronise movements/clocks; synchronise with','动词，使动作、时钟或过程在时间上一致。','the drum provides a shared timing cue.','动作'),M('The dancers synchronised their steps by deliberately moving at different times from the drum.','The dancers synchronised their steps with the drumbeat.','synchronise表示时间一致，故意错开鼓点与其相反。','meaning'),[Q(1,'The dancers synchronise their steps means they…','make the steps happen together in time','choose unrelated steps','summarise the dance','That is the verb’s timing sense.','meaning'),Q(1,'What helps them stay together?','The drum provides a common beat','A synagogue bell rings at random','A summary of the routine','The context identifies a shared timing signal.','context'),Q(1,'Which spelling is standard in British English?','synchronise','synchronyze','synchronizee','The -ise spelling is a standard British variant.','spelling'),Q(1,'Synchronise combines syn- “together” with…','chronos, “time”','ops, “view”','onyma, “name”','The time element explains the word’s meaning.','word-formation')]);
P('synchronization','Synchronization is formed from synchronize + -ation; it names the process or result of making separate events happen together or match in timing.',C('synchronization.s1','媒体','The editor corrected the lip synchronization so the actors’ words matched the soundtrack.','剪辑师修正了口型同步，让演员的台词与配乐对得上。','synchronization of sound and image; time synchronization','名词，指使动作或信号同时、对时的过程或结果。','mouth movements are aligned with audio.','媒体'),M('The film’s synchronization was perfect even though every spoken word began several seconds after the matching mouth movement.','The film’s synchronization matched each spoken word to the actors’ mouth movements.','同步要求口型和声音在时间上对齐。','meaning'),[Q(1,'Lip synchronization aligns…','mouth movements with the soundtrack','the actors with a synagogue','a summary with a title','That is the media use of synchronization.','meaning'),Q(1,'What did the editor correct?','The timing between speech and mouth movement','The actors’ essay collection','The medical symptom','The context is about matching video and audio timing.','context'),Q(1,'Which phrase is natural?','synchronization of sound and image','synchronization sound image at','synchronize of sound and image','Of introduces the two elements brought into time alignment.','grammar'),Q(1,'Synchronization is formed from synchronize plus…','-ation','-er','-ous','The suffix -ation forms a noun for the process or result.','word-formation')]);
P('synchronize','Synchronize combines syn- “together” and Greek chronos “time” with -ize; it means make devices match, or happen together in time.',[C('synchronize.s1','设备','Please synchronize your watch with the station clock before the race begins.','比赛开始前，请把手表与车站时钟校准到同一时间。','synchronize watches/clocks; synchronize A with B','动词，使钟表或机器显示同一时间。','one clock is adjusted to match another.','设备'),C('synchronize.s2','同时','The stage lights synchronize with the music during the chorus.','合唱部分时，舞台灯光与音乐同步变化。','synchronize with; events synchronize','动词，也可指事情同时发生或动作协调一致。','light changes match the music’s timing.','同时')],M('She synchronized her watch with the station clock by setting it three hours later than the clock.','She synchronized her watch with the station clock by matching their displayed times.','校准时间需要使两只钟显示一致，而不是故意错开。','meaning'),[Q(1,'Synchronize your watch with the station clock means…','set both to show the same time','remove the watch strap','make the station close','Sense 1 is matching clock time.','meaning'),Q(2,'Lights synchronize with music when…','their changes occur in time with the music','they remain off throughout the song','the music is summarized','Sense 2 describes events moving together.','context'),Q(1,'Which construction is correct?','synchronize A with B','synchronize A to B withly','synchronize with A B at','With introduces the thing used as the timing match.','grammar'),Q(1,'Chronos in synchronize means…','time','name','assembly','The Greek element explains the timing sense.','word-formation')]);
P('synchronizer','Synchronizer is formed from synchronize + -er; it names a mechanism that coordinates timing, such as a device in a gearbox or camera flash.',C('synchronizer.s1','机械','The mechanic replaced a worn gearbox synchronizer so the gears could engage smoothly.','技工更换了磨损的变速箱同步器，使齿轮能平顺啮合。','gearbox/camera-flash synchronizer; replace a synchronizer','名词，指协调两个动作或信号时机的装置。','the mechanism helps rotating parts engage at matching speeds.','机械'),M('The gearbox synchronizer made shifting rougher by forcing the gears to engage at mismatched speeds.','The gearbox synchronizer helped the gears engage at matching speeds.','同步器的作用是协调速度和时机，不是制造错速。','meaning'),[Q(1,'A gearbox synchronizer is…','a mechanism that coordinates timing or speed','a driver who changes jobs','a list of related words','The source entry defines a mechanical timing device.','meaning'),Q(1,'Why did the mechanic replace it?','The worn part no longer helped the gears engage smoothly','It was used to summarize an essay','It caused the room to become stuffy','The context connects the part with smooth gear engagement.','context'),Q(1,'Which phrase is natural?','replace a worn synchronizer','replace a synchronizedly','synchronizer replace wornly','Synchronizer is the name of the part being replaced.','grammar'),Q(1,'Synchronizer is formed from synchronize plus…','-er','-ment','-al','The suffix names a device that performs the synchronizing action.','word-formation')]);
P('synchronous','Synchronous combines Greek syn- “together” with chronos “time”; it describes events occurring together or devices operating at a matching rate.',C('synchronous.s1','时间','The two clocks remained synchronous throughout the week-long experiment.','整个为期一周的实验中，两只钟一直保持同步。','synchronous signals/operation; synchronous with','形容词，指同时发生或按相配频率运作。','the clocks continue to show matched timing.','时间'),M('The clocks were synchronous even though one gained ten minutes every hour and never matched the other.','The clocks were synchronous because they kept the same time.','synchronous表示时序或频率相配，明显不断偏差与之相反。','meaning'),[Q(1,'Synchronous clocks…','show matching time throughout operation','run at unrelated rates','are a kind of essay collection','That is the adjective’s timing sense.','meaning'),Q(1,'What happened during the experiment?','The clocks stayed in step for a week','One clock gained ten minutes every hour','The clocks were never started','The context describes sustained matching.','context'),Q(1,'Which phrase is natural?','synchronous with the signal','synchronous to signal at','a synchronous of signal','With introduces the event or signal matched in time.','collocation'),Q(1,'Synchronous contains Greek chronos, meaning…','time','together','touch','The root chronos is the time element.','word-formation')]);
P('synchrotron','Synchrotron is a scientific compound coined from synchro(nous) and cyclotron; it names a circular particle accelerator that keeps particles in step with a changing magnetic field.',C('synchrotron.s1','物理','Researchers used the synchrotron’s intense X-rays to examine the protein crystals.','研究人员用同步加速器产生的强X射线检查蛋白质晶体。','synchrotron radiation; synchrotron facility','名词，指让带电粒子与逐渐增强的磁场同步、沿环形轨道加速的设备。','the facility accelerates particles and produces useful radiation.','物理'),M('The synchrotron accelerated charged particles in a straight line without coordinating them with any magnetic field.','The synchrotron accelerated charged particles around a circular path in step with the magnetic field.','同步加速器通过协调粒子与变化磁场使其沿环形路径加速。','meaning'),[Q(1,'A synchrotron is…','a circular accelerator for charged particles','a Jewish house of worship','a small tablet of medicine','That is the physics sense.','meaning'),Q(1,'What did researchers study with its X-rays?','Protein crystals','A written synopsis','A plant tableland','The example identifies a scientific use.','context'),Q(1,'Which phrase is natural?','synchrotron radiation','synchrotronize radiation','a radiation synchrotron ofly','Radiation is the output associated with the facility.','collocation'),Q(1,'The name synchrotron combines synchro- with…','cyclotron','synopsis','syndrome','The scientific compound reflects its synchronous operation and accelerator type.','word-formation')]);
P('syncope','Syncope comes from Greek synkope, “cutting off,” through medical Latin; it is a brief faint caused by a temporary reduction in blood flow to the brain.',C('syncope.s1','医学','The patient recovered quickly after syncope caused him to faint in the waiting room.','患者在候诊室因晕厥短暂昏倒后很快恢复。','an episode of syncope; faint from syncope','名词，指脑部血流暂时减少引起的短时失去知觉。','brief loss of consciousness is followed by rapid recovery.','医学'),M('Syncope made her faint for several hours because blood flow to her brain increased steadily.','Syncope made her faint briefly after blood flow to her brain temporarily fell.','syncope是血流短暂下降导致的短时昏厥，不是数小时昏迷或血流增加。','meaning'),[Q(1,'Syncope is…','a short faint linked to reduced blood flow to the brain','a long formal discussion','a word with the same meaning','That is the medical definition.','meaning'),Q(1,'What happened to the patient?','He fainted briefly and recovered quickly','He entered a research accelerator','He stayed unconscious for several hours','The context emphasizes the brief episode and recovery.','context'),Q(1,'Which phrase is natural?','an episode of syncope','a syncope with episode ofly','syncope episode a of','Episode of is a common way to describe an occurrence.','grammar'),Q(1,'Greek synkope meant…','cutting off','bringing together for discussion','same-time operation','The historical word refers to cutting off, reflected in a brief loss of consciousness.','word-formation')]);
P('syndicate','Syndicate came through French syndicat from syndic, a representative; it can be a group joined for business or the act of selling a feature to many outlets.',[C('syndicate.s1','商业','A syndicate of investors bought the old factory and plans to convert it into housing.','一个投资者财团买下了旧工厂，计划把它改造成住宅。','a business/investment syndicate; form a syndicate','名词，指为商业目的联合起来的一群公司或个人。','investors pool resources for one purchase.','商业'),C('syndicate.s2','媒体','The newspaper syndicates the weekly column to regional papers across the country.','这家报社把每周专栏授权给全国各地的地区报纸刊登。','syndicate a column/program; syndicated content','动词，指把文章、漫画或节目出售给多家媒体。','one column is distributed to many outlets.','媒体')],M('The paper syndicated its column by selling it exclusively to one reader and no other outlet.','The paper syndicated its column to many regional publications.','syndicate媒体内容是向多家媒体分销，不是只卖给一个读者。','meaning'),[Q(1,'An investment syndicate is…','a group pooling resources for business','a single newspaper reader','a medical faint','Sense 1 concerns a business group.','meaning'),Q(2,'A newspaper syndicates a column when it…','sells it to many publications','keeps it from every other outlet','turns it into a synagogue','Sense 2 is media distribution.','context'),Q(1,'Which phrase is natural?','syndicate a comic strip nationwide','syndicate nationwide to a comic only','syndication a comic strips','The verb takes the content as its object.','grammar'),Q(1,'Syndicate came through French from syndic, meaning…','a representative','a summary','a chromosome pair','The historical source named a representative or steward.','word-formation')]);
P('syndrome','Syndrome comes from Greek syndromē, “concurrence,” from syn- “together” and dromos “running”; it can be a cluster of medical signs or a recurring social pattern.',[C('syndrome.s1','医学','The physician ordered further tests because the patient’s symptoms suggested a rare syndrome.','医生安排了进一步检查，因为病人的症状提示可能患有罕见综合征。','a medical syndrome; syndrome associated with','名词，指一组同时出现的医学征象。','several signs occur together and prompt evaluation.','医学'),C('syndrome.s2','社会','The author calls the pattern a “winner-takes-all syndrome” in large cities.','作者把大城市中的这种模式称为“赢家通吃综合征”。','a social syndrome; syndrome of a problem','名词，也可指某种问题常见的一组行为或事件。','a repeated social pattern is given a label.','社会')],M('The doctor diagnosed a syndrome from one unrelated event even though no signs ever appeared together.','The doctor considered a syndrome because several related signs appeared together.','syndrome指一组共同出现的征象，单一且无关联的事件不足以构成该模式。','meaning'),[Q(1,'A medical syndrome is…','a set of signs that appear together','a single unrelated word','a scientific accelerator','That is the medical sense.','meaning'),Q(2,'A “winner-takes-all syndrome” refers to…','a recurring pattern associated with a social problem','a formal disease diagnosis only','a collection of essays','Sense 2 applies the word to a pattern of behavior or events.','context'),Q(1,'Which phrase is natural?','a syndrome of urban problems','a syndrome urbanly of problem','a symptom of syndromeing','Of introduces the problem pattern associated with the syndrome.','collocation'),Q(1,'Greek syndromē meant…','concurrence or things running together','a long narrow strip','a precise grammar rule','The historical sense reflects signs or events occurring together.','word-formation')]);
P('synonym','Synonym comes from Greek synonymon, from syn- “with” and onyma “name”; it is a word or phrase with nearly the same meaning as another.',C('synonym.s1','词汇','“Begin” is a synonym for “start” in many everyday sentences.','在许多日常句子中，begin 是 start 的近义词。','a synonym for/of a word; near synonym','名词，指与另一个词或短语意思几乎相同的词。','the two verbs can replace one another in many contexts.','词汇'),M('“Begin” is a synonym for “start” because the two words always mean complete the same action.','“Begin” is a synonym for “start” because both can mean commence.','synonym表示意思相近，不能把两词误释为“开始”和“完成”。','meaning'),[Q(1,'A synonym for begin is…','start','finish','accelerator','That word has a similar meaning.','meaning'),Q(1,'Why can begin and start be synonyms here?','Both can mean commence an action','One means commence and the other means stop','They are the same spelling','The explanation states their shared sense.','context'),Q(1,'Which phrase is natural?','a synonym for “rapid”','a synonym ofly “rapid”','a synonymous for “rapid”','For introduces the word whose meaning is matched.','grammar'),Q(1,'Greek synonymon combines syn- “with” and…','onyma, “name”','chronos, “time”','dromos, “run”','The Greek elements refer to names or words with similar meaning.','word-formation')]);
P('synonymous','Synonymous is formed from synonym + -ous; it means having the same or nearly the same meaning, or being so closely associated that one suggests the other.',C('synonymous.s1','词义','In this passage, “purchase” is synonymous with “buy,” though it sounds more formal.','在这段文字里，purchase 与 buy 意思相同，不过语气更正式。','synonymous with; nearly synonymous terms','形容词，指意义相同或相近。','the two verbs share a meaning but differ in register.','词义'),M('The terms are synonymous, but one means “buy” and the other means “sell.”','The terms are synonymous because both mean “buy.”','buy和sell含义相反，不是同义词。','confusable'),[Q(1,'If purchase is synonymous with buy, the words…','have the same meaning in this context','mean buy and sell respectively','are spelled identically','That is the adjective’s meaning.','meaning'),Q(1,'What difference remains between purchase and buy here?','Purchase sounds more formal','Purchase means the opposite','There is no shared sense','The context notes a register difference despite similar meaning.','context'),Q(1,'Which construction is correct?','synonymous with “buy”','synonymous to “buy” at','synonymously with buyed','The standard construction is synonymous with.','collocation'),Q(1,'Synonymous is formed from synonym plus…','-ous','-ize','-ship','The suffix forms an adjective meaning having the quality of a synonym.','word-formation')]);
P('synopsis','Synopsis comes from Greek synopsis, “general view,” from syn- “together” and opsis “view”; it is a brief account of a longer work or proposal.',C('synopsis.s1','阅读','Read the film synopsis before the screening, but avoid reviews that reveal the ending.','放映前先读剧情简介，但不要看会泄露结局的影评。','a brief synopsis; synopsis of a proposal/story','名词，指对较长作品、计划或论点的简短概述。','a short account helps the reader decide what to expect.','阅读'),M('The synopsis of the novel reproduced every chapter in full and was longer than the book.','The synopsis briefly summarizes the novel’s main plot.','synopsis是简短概要，不是完整重印每一章。','meaning'),[Q(1,'A film synopsis is…','a brief summary of the story','the full film transcript','a medical sign','That is the definition.','meaning'),Q(1,'Why read it before the screening?','It gives a short overview of what to expect','It contains every scene in full','It guarantees the ending is spoiled','The context says it provides a brief account.','context'),Q(1,'Which phrase is natural?','a synopsis of the proposal','a synopsis the proposal aboutly','a synopsis to proposal in','Of introduces the work being summarized.','collocation'),Q(1,'Greek synopsis meant…','a general view','a name used together','a person’s natural ability','The word’s roots describe viewing things together as an overview.','word-formation')]);
P('syntactic','Syntactic is formed from syntax + -ic; it means relating to the rules for how words combine into phrases and sentences.',C('syntactic.s1','语言学','The student corrected a syntactic error by moving the adverb next to the verb it modified.','学生把副词移到它所修饰的动词旁边，纠正了一个句法错误。','syntactic structure/error; syntactic rules','形容词，指与句子中词语组合和排列规则有关。','word order is corrected.','语言学'),M('The sentence has a syntactic error because its spelling is wrong, although every word is in a valid position.','The sentence has a syntactic error because the words are arranged incorrectly.','句法涉及词语组合和排列，不是单词拼写。','distinction'),[Q(1,'A syntactic error concerns…','how words are arranged in a phrase or sentence','the historical origin of a word only','the color of a printed table','That is the adjective’s linguistic sense.','meaning'),Q(1,'What did the student change?','The position of an adverb','The spelling of every noun','The meaning of the whole paragraph','The context describes a word-order correction.','context'),Q(1,'Which phrase is natural?','syntactic structure','syntacticality structure','syntaxic structurely','Syntactic is the standard adjective before structure.','grammar'),Q(1,'Syntactic is formed from syntax plus…','-ic','-er','-less','The suffix -ic forms an adjective related to syntax.','word-formation')]);
P('syntax','Syntax comes from Greek syntaxis, “arrangement,” from syn- “together” and tassein “arrange”; it names sentence structure or a system’s command rules.',[C('syntax.s1','语言学','Students often revise the syntax of formal essays to make each clause easier to follow.','学生常修改正式文章的句法，让每个从句更容易理解。','word order/sentence syntax; syntax of a language','名词，指语言中的词序与句子结构规则。','clauses are rearranged for clarity.','语言学'),C('syntax.s2','计算机','The parser checks the syntax of each command before the program runs.','程序运行前，解析器会检查每条命令的语法结构。','command/code syntax; syntax error','名词，也指规定系统中符号或指令如何排列的规则。','the software validates command structure.','计算机')],M('The command passed the syntax check even though its symbols were in an order the parser rejected.','The command failed the syntax check because its symbols were in an invalid order.','syntax检查指令的排列规则；解析器拒绝说明其结构不合法。','meaning'),[Q(1,'Syntax in a language governs…','word order and sentence structure','the pronunciation of one consonant only','the content of an essay','Sense 1 is the language meaning.','meaning'),Q(2,'A command’s syntax tells the system…','how its symbols may be arranged','which employee should run it','how quickly it can be printed','Sense 2 concerns formal command rules.','context'),Q(1,'Which phrase is natural?','the syntax of the sentence','the syntax on the sentence orderly','the sentence syntaxly of','Of introduces the language or system whose rules are described.','grammar'),Q(1,'Greek syntaxis meant…','arrangement','fainting','a collection of essays','The historical source directly reflects ordered arrangement.','word-formation')]);
P('synthesis','Synthesis comes from Greek synthesis, “putting together,” from syn- “together” and tithenai “put”; it means combining ideas or making a compound.',[C('synthesis.s1','写作','The review offers a synthesis of findings from three studies rather than summarizing each one separately.','这篇综述综合了三项研究的发现，而不是逐项单独概述。','a synthesis of ideas/evidence; write a synthesis','名词，指把不同想法或材料结合成连贯整体。','separate findings are integrated.','写作'),C('synthesis.s2','化学','The synthesis of the medicine required two controlled reactions in the laboratory.','这种药物的合成需要在实验室进行两次受控反应。','chemical synthesis; synthesis of a compound','名词，也指由较简单物质制备化合物的过程。','a compound is produced through reactions.','化学')],M('The essay’s synthesis kept every study isolated and refused to connect their findings.','The essay’s synthesis connected findings from the three studies into one account.','synthesis表示整合不同材料，孤立呈列不是综合。','meaning'),[Q(1,'A synthesis of three studies…','combines their findings into a connected whole','copies one study and ignores the others','lists unrelated titles only','Sense 1 is intellectual integration.','meaning'),Q(2,'Chemical synthesis is…','making a compound from simpler substances','summarizing research articles','separating a compound into unrelated headlines','Sense 2 is the chemistry process.','context'),Q(1,'Which phrase is natural?','a synthesis of the evidence','a synthesis the evidence withly','synthesis to evidence by','Of introduces the materials brought together.','collocation'),Q(1,'Greek synthesis literally conveyed…','putting together','cutting off','a general view','The roots syn- and tithenai mean together and put.','word-formation')]);
P('synthesize','Synthesize is formed from synthesis + -ize; it means produce a substance through a chemical/artificial process or combine information into one account.',[C('synthesize.s1','化学','The chemists synthesize the medicine in small batches and test each sample for purity.','化学家分批合成这种药物，并检测每份样品的纯度。','synthesize a compound; synthesize from simpler materials','动词，指通过化学或人工过程制出物质。','laboratory reactions produce a substance.','化学'),C('synthesize.s2','研究','For her conclusion, Mei synthesized results from interviews, surveys, and field notes.','梅在结论中综合了访谈、问卷和实地笔记的结果。','synthesize information/findings; synthesize A into B','动词，也指把分散信息综合成一个整体说明。','several evidence sources become one account.','研究')],M('Mei synthesized the study results by reporting each source separately without relating any of them.','Mei synthesized the study results into one account that connected the evidence.','综合信息要求建立联系，而非彼此孤立地罗列。','meaning'),[Q(1,'Chemists synthesize a medicine when they…','produce it through a chemical process','summarize a medical article','synchronize two watches','Sense 1 is chemical production.','meaning'),Q(2,'Mei synthesized interview and survey results by…','combining them into one connected account','keeping every source separate','removing the evidence from her conclusion','Sense 2 is integration of information.','context'),Q(1,'Which construction is correct?','synthesize findings into a conclusion','synthesize to findings for conclusion','synthesizingly findings a conclusion','Into introduces the resulting integrated account.','grammar'),Q(1,'Synthesize is formed from synthesis plus…','-ize','-ous','-ity','The suffix forms a verb meaning make or combine into a synthesis.','word-formation')]);
P('synthesizer','Synthesizer is formed from synthesize + -er; it names an electronic keyboard that creates sounds or a person who combines ideas.',[C('synthesizer.s1','音乐','Mika layered a flute tone and a bass line on the synthesizer during rehearsal.','彩排时，米卡用合成器叠加了长笛音色和低音声部。','play/use a synthesizer; electronic synthesizer','名词，指能生成并塑造音色的电子键盘乐器。','the keyboard produces layered musical sounds.','音乐'),C('synthesizer.s2','写作','As a synthesizer of history and oral testimony, Chen links facts that other writers treat separately.','作为历史与口述证词的综合者，陈把其他作者分开处理的事实联系起来。','a synthesizer of ideas; skilled synthesizer','名词，也指把不同想法或材料整合起来的人。','one person connects separate sources.','写作')],M('Mika played a synthesizer, a purely acoustic drum that could not create or shape electronic tones.','Mika played a synthesizer that generated and shaped electronic tones.','synthesizer此处指能产生电子音色的键盘，不是纯原声鼓。','meaning'),[Q(1,'A synthesizer used in rehearsal is…','an electronic keyboard that creates and shapes sounds','a musical essay collection','a device that measures blood flow','Sense 1 is the instrument meaning.','meaning'),Q(2,'A synthesizer of history and testimony is…','a person who combines separate ideas or sources','a keyboard with no sound','a speaker who refuses to connect evidence','Sense 2 refers to someone who integrates material.','context'),Q(1,'Which phrase is natural?','play a melody on a synthesizer','play a synthesizerly melody','synthesizer the melody on play','On introduces the instrument used.','collocation'),Q(1,'Synthesizer is formed from synthesize plus…','-er','-ous','-ment','The suffix names an instrument or person that performs the action.','word-formation')]);
P('synthetic','Synthetic comes from Greek synthetikos, “put together”; it describes material made by chemical processes or something that is not genuine.',[C('synthetic.s1','材料','The jacket’s synthetic fabric dries quickly and does not come from an animal or plant fiber.','夹克的合成面料干得很快，并非取自动物或植物纤维。','synthetic material/fiber; synthetic fabric','形容词，指由化学方法从原料制成，而非直接取自自然来源。','the cloth is chemically manufactured.','材料'),C('synthetic.s2','态度','Her synthetic enthusiasm faded as soon as the cameras were turned off.','摄像机一关，她装出来的热情马上消失了。','synthetic smile/enthusiasm; sound synthetic','形容词，也指不真诚、为了给别人留下印象而做出来的。','the displayed excitement is put on.','态度')],M('Her synthetic enthusiasm was genuine and spontaneous, with no attempt to impress the camera.','Her synthetic enthusiasm was put on for the camera.','synthetic用于态度时表示不真诚、装出来的，与真诚自发相反。','meaning'),[Q(1,'Synthetic fabric is…','made through chemical processes rather than taken directly from nature','woven only from natural wool','a written summary','Sense 1 concerns manufactured material.','meaning'),Q(2,'Synthetic enthusiasm is…','put on rather than sincere','an electronic keyboard sound','a medical condition','Sense 2 describes insincerity.','context'),Q(1,'Which phrase is natural?','a synthetic fiber','a synthetically fiber','a synthesis fiberly','Synthetic is an adjective modifying fiber.','grammar'),Q(1,'Synthetic comes from Greek synthetikos, related to…','putting together','speaking together','cutting off','The source refers to things put together or compounded.','word-formation')]);
P('syringe','Syringe comes through French and Latin from Greek syrinx, “pipe”; it names a device for moving liquid and can also mean clean a cavity by using one.',[C('syringe.s1','医疗','The nurse opened a sterile syringe before drawing the vaccine from the vial.','护士先打开无菌注射器，再从小瓶中抽取疫苗。','use/fill a syringe; syringe with a needle','名词，指带细管或针头、用来注入或抽取液体的器械。','the device draws liquid from a vial.','医疗'),C('syringe.s2','清洗','The clinician syringed the wound with sterile saline before applying a bandage.','临床医生包扎前用无菌盐水冲洗伤口。','syringe a wound/cavity; syringe with saline','动词，指用注射器把液体喷入伤口或体腔进行清洗。','liquid is flushed through the device.','清洗')],M('The nurse used a syringe to inject a vaccine without any tube, needle, or way to move liquid.','The nurse used a syringe with a needle to draw up and inject the vaccine.','注射器依靠细管或针头输送液体，不可能没有液体通道。','meaning'),[Q(1,'A medical syringe is…','a device for injecting or withdrawing liquid','a machine for synchronizing clocks','a flat computer','Sense 1 is the instrument meaning.','meaning'),Q(2,'The clinician syringed the wound means the clinician…','flushed liquid through it using the device','stitched it without cleaning','summarized the injury','Sense 2 is the verb meaning irrigate.','context'),Q(1,'Which phrase is natural?','draw medicine into a syringe','draw medicine a syringe intoly','syringe into draw medicine','Into marks the container receiving the liquid.','collocation'),Q(1,'Greek syrinx meant…','pipe or tube','sweet liquid','a set of medical signs','The Greek source referred to a tube-like object.','word-formation')]);
P('syrup','Syrup came through Old French sirop, and perhaps Italian siroppo, from Arabic sharab, “beverage,” from shariba, “drink”; it is a thick sweet liquid used in food or as a vehicle for medicine.',C('syrup.s1','食物','Pour a little maple syrup over the pancakes while they are still warm.','趁煎饼还热时，在上面淋一点枫糖浆。','maple/fruit syrup; pour syrup over','名词，指糖和水或果汁熬成的黏稠甜液，也用于药剂。','the thick liquid sweetens food.','食物'),M('She poured syrup over the pancakes, but the liquid was thin, unsweetened water.','She poured thick, sweet maple syrup over the pancakes.','syrup是黏稠甜液，不是稀薄无糖的水。','meaning'),[Q(1,'Maple syrup is…','a thick sweet liquid','a flat piece of stone','a formal discussion','That is the food sense.','meaning'),Q(1,'Why pour it over pancakes?','It sweetens the food','It checks the syntax','It synchronizes the clocks','The context shows syrup being used as a topping.','context'),Q(1,'Which phrase is natural?','a bottle of cough syrup','a cough of syrup bottlely','syrup a bottle from cough','A bottle of introduces a quantity of the liquid.','grammar'),Q(1,'Arabic sharab, an earlier source of syrup, meant…','drink','pipe','arrangement','The historical Arabic word referred to a drink.','word-formation')]);
P('system','System comes from Greek systema, “organized whole,” from syn- “together” and histanai “set”; it can mean connected parts, an organized method, or a group of organs.',[C('system.s1','设备','The heating system stopped working when a pipe froze in the basement.','地下室的一根管道冻住后，供暖系统停止了工作。','heating/security system; system of parts','名词，指一组相互关联、共同运作的部分。','the pipe is one component of the whole.','设备'),C('system.s2','方法','Our office uses a color-coded filing system to find contracts quickly.','我们办公室用颜色编码的归档制度快速查找合同。','a system for doing something; filing system','名词，也指做事的一套有组织的方法。','the procedure organizes records.','方法'),C('system.s3','生理','Regular exercise supports the cardiovascular system.','规律运动有助于心血管系统健康。','nervous/digestive system; body system','名词，也指共同完成一种功能的一组器官。','related organs perform one bodily function.','生理')],M('The heating system worked as a system even though its pipes, controls, and heater never interacted.','The heating system worked because its pipes, controls, and heater operated together.','system由相互关联、共同运作的部分组成。','meaning'),[Q(1,'A heating system is…','related parts working together','one unrelated pipe','a summary of a report','Sense 1 concerns connected components.','meaning'),Q(2,'A filing system is…','an organized method for storing and finding records','a group of organs','a formal conference','Sense 2 is a procedure.','context'),Q(3,'The cardiovascular system is…','organs that work together for a bodily function','a color-coded office shelf only','a group of investors','Sense 3 is a bodily organ system.','meaning'),Q(1,'Greek systema referred to…','an organized whole','a tiny label','a social prohibition','The Greek source describes things set together as a whole.','word-formation')]);
P('systematic','Systematic combines system with an adjectival ending; it means done according to a fixed method, or as a recurring part of an organized practice.',[C('systematic.s1','研究','The team conducted a systematic review, checking each study against the same criteria.','团队进行了一次系统综述，用同一套标准审查每项研究。','systematic study/review/search; systematic approach','形容词，指依照固定计划或体系、有步骤地进行。','each study is evaluated by the same procedure.','研究'),C('systematic.s2','社会','The report documented systematic unfair treatment of applicants from one neighborhood.','报告记录了对某个社区申请者的系统性不公平对待。','systematic discrimination/unfairness; systematic abuse','形容词，也指某种作为体制惯例反复实施的做法，常含贬义。','unfair treatment recurs as part of a process.','社会')],M('The review was systematic even though researchers selected studies randomly and changed criteria for each one.','The review was systematic because researchers applied the same planned criteria to every study.','systematic要求有固定方法，随机换标准与之相反。','meaning'),[Q(1,'A systematic review uses…','a fixed method applied consistently','different criteria for every study','no plan at all','Sense 1 is methodical procedure.','meaning'),Q(2,'Systematic unfair treatment is…','unfairness repeated as part of an organized practice','one accidental mistake','a fair rule applied equally','Sense 2 is the institutional pattern sense.','context'),Q(1,'Which phrase is natural?','a systematic search for evidence','a systematicly search evidence','a system searchingly evidence','Systematic is an adjective before search.','grammar'),Q(1,'Systematic is formed from system plus…','an adjectival ending','the noun syrup','the prefix syncope','The adjective means arranged or carried out as a system.','word-formation')]);
P('systematically','Systematically is formed from systematic + -ally; it means according to a fixed method, step by step.',C('systematically.s1','方法','The archivist systematically checked every box against the inventory before moving the collection.','档案管理员搬运藏品前，按清单逐箱系统核查。','systematically examine/check/record; proceed systematically','副词，表示依照固定方法逐步进行。','every box is checked using the same ordered method.','方法'),M('The archivist systematically checked the boxes by choosing random boxes and skipping the rest.','The archivist systematically checked every box in order against the inventory.','systematically要求有条理地逐步核查，随机漏查不符合。','meaning'),[Q(1,'Systematically checking boxes means…','checking them methodically in an ordered way','choosing a few at random and skipping the rest','summarizing their contents without opening them','The adverb describes consistent procedure.','meaning'),Q(1,'What did the archivist use as a reference?','The inventory','A syrup recipe','A musical keyboard','The context identifies the list used for comparison.','context'),Q(1,'Which sentence is natural?','The team systematically reviewed each file.','The systematically team reviewed each file.','The team reviewed each systematically file.','Systematically modifies the verb reviewed.','grammar'),Q(1,'Systematically is formed from systematic plus…','-ally','-ness','-er','The suffix makes the manner adverb.','word-formation')]);
P('systematization','Systematization is formed from systematize + -ation; it is the process of arranging facts, rules, or work into an ordered system.',C('systematization.s1','档案','The systematization of the archive took two years because records came from many offices.','由于档案来自许多部门，整理成系统花了两年。','systematization of data/rules; process of systematization','名词，指把材料或工作整理成有秩序体系的过程。','records are organized into a consistent structure.','档案'),M('The systematization of the archive left every record randomly scattered and impossible to find.','The systematization of the archive arranged records into a searchable order.','systematization是建立有序体系，不是任其散乱。','meaning'),[Q(1,'Systematization of an archive is…','organizing records into an ordered system','destroying every record','reading one document aloud','That is the noun’s process meaning.','meaning'),Q(1,'Why did this archive take two years to systematize?','Records came from many offices','It had only one page','It was a synchrotron','The example gives the scale and complexity.','context'),Q(1,'Which phrase is natural?','systematization of the records','systematization records byly','systematize of recordation','Of introduces the material being organized.','grammar'),Q(1,'Systematization is formed from systematize plus…','-ation','-ous','-ful','The suffix forms a noun naming the process.','word-formation')]);
P('systematize','Systematize combines system + -ize; it means organize items or procedures so that they follow a consistent plan.',C('systematize.s1','整理','The editor systematized the spelling variants and listed them under consistent headings.','编辑把拼写变体系统整理，并按统一标题列出。','systematize data/rules; systematize a procedure','动词，指把项目或流程组织成一致的体系。','variants are sorted by a common rule.','整理'),M('The editor systematized the variants by placing each one randomly under unrelated headings.','The editor systematized the variants under consistent headings.','systematize要求建立一致的组织规则，随机归类与之相反。','meaning'),[Q(1,'To systematize spelling variants is to…','organize them under a consistent plan','mix them randomly','remove all spellings','That is the verb’s meaning.','meaning'),Q(1,'How did the editor arrange the variants?','Under consistent headings','In a random pile','As a group of essays','The example specifies the organizing method.','context'),Q(1,'Which phrase is correct?','systematize the filing process','systematize to filing processly','systematically the filing processize','The verb takes the process as its direct object.','grammar'),Q(1,'Systematize is formed from system plus…','-ize','-ous','-ment','The suffix creates a verb meaning arrange into a system.','word-formation')]);
P('systems','Systems is the regular plural of system; it refers to multiple sets of connected parts or rules that operate together.',C('systems.s1','设备','The hospital upgraded its computer systems before opening the new wing.','医院在新楼翼开放前升级了计算机系统。','computer/security systems; systems of rules','名词复数，指多组彼此关联、共同运行的部分或规则。','several coordinated technical networks are upgraded.','设备'),M('The hospital upgraded its computer systems, but installed only one unconnected component with no other parts.','The hospital upgraded several connected computer systems.','systems是多套由相关部分构成的整体，不是一个孤立部件。','meaning'),[Q(1,'Computer systems are…','sets of connected parts that work together','one isolated part only','a single medical symptom','That is the plural sense.','meaning'),Q(1,'What did the hospital do before opening the wing?','Upgraded its computer systems','Removed the entire filing system','Held a symposium','The context states the action and timing.','context'),Q(1,'Which sentence is correct?','The new systems are ready.','The new system are ready.','The new systems is ready.','Systems is plural and takes the plural verb are.','grammar'),Q(1,'Systems is the plural form of…','system','systematic','symptom','The lemma is the regular plural of system.','plural')]);
P('tab','Tab is recorded in English for a small projecting flap or label; the bar-bill and computer-interface senses developed separately, and some earlier details are uncertain.',[C('tab.s1','物件','Pull the plastic tab to open the battery compartment without using a tool.','拉动塑料拉片即可打开电池仓，无需使用工具。','pull a tab; pull-tab can','名词，指从门、抽屉或包装上突出来、便于拉开的部分。','the projecting piece provides a grip.','物件'),C('tab.s2','标签','A paper tab on each folder shows the client’s name and filing date.','每个文件夹上的纸标签都标明客户姓名和归档日期。','file/index tab; labeled tab','名词，也指贴在物品上标明名称或价格的小纸片。','the label identifies the folder.','标签'),C('tab.s3','账单','They opened a tab at the café and paid the combined bill before leaving.','他们在咖啡馆记了账，离开前结清了总账单。','run/open/settle a tab; bar tab','名词，指稍后结算的吃喝账单。','charges accumulate and are paid later.','账单'),C('tab.s4','界面','Open a new tab in the browser to compare the two train schedules.','在浏览器中打开新标签页，比较两份列车时刻表。','browser tab; tab key','名词，指在屏幕上切换页面的区域，也可指Tab键。','a new page is opened within the interface.','界面')],M('They opened a tab at the café, paid each item immediately, and had no running bill to settle.','They opened a tab at the café and paid the accumulated bill before leaving.','开账意味着先累计消费、之后结账，不是每项即时付款。','meaning'),[Q(1,'Pull the battery-compartment tab means pull…','a small projecting flap','a computer keyboard shortcut list','a whole table','Sense 1 is the flap meaning.','meaning'),Q(2,'A folder tab shows…','a label such as a client’s name','the total café bill','a medical symptom','Sense 2 identifies the label use.','context'),Q(3,'Opening a tab at a café means…','running a bill to pay later','opening a browser page','pulling a plastic latch','Sense 3 is the delayed-payment meaning.','meaning'),Q(4,'A new browser tab is…','an interface area for another page','a paper label on a folder','a café bill','Sense 4 is the computer-interface sense.','context')]);
P('table','Table comes from Latin tabula, “board or flat surface”; it can be furniture, information in rows and columns, or a verb meaning submit or postpone a proposal.',[C('table.s1','家具','The family gathered around the kitchen table for breakfast.','一家人围坐在厨房的桌子旁吃早餐。','a kitchen/dining table; sit at the table','名词，指有平整桌面、用于吃饭或工作的家具。','people gather at a piece of furniture.','家具'),C('table.s2','数据','The table lists monthly rainfall for all twelve districts.','这张表列出了十二个地区每月的降雨量。','a data/table of figures; table rows and columns','名词，也指按行列排列的数据。','information is organized in rows and columns.','数据'),C('table.s3','议事','The committee tabled the proposal until it could review the budget.','委员会把提案暂缓，等预算审查完成后再处理。','table a proposal/motion; table an issue','动词，可指提交议事，也可在某些英语地区指暂缓讨论。','consideration is deliberately postponed here.','议事')],M('The committee tabled the proposal until June by voting to discuss and decide it immediately.','The committee tabled the proposal until June, postponing a decision.','此语境中tabled表示暂缓，不是立即讨论决定。','meaning'),[Q(1,'The family sat at a kitchen table, a…','piece of furniture with a flat top','list arranged in rows and columns','proposal postponed until June','Sense 1 is the furniture meaning.','meaning'),Q(2,'A table of rainfall figures is…','data arranged in rows and columns','a piece of kitchen furniture','a discussion between governments','Sense 2 is the information display.','context'),Q(3,'The committee tabled the proposal until June means it…','postponed considering it','built a wooden table','approved it immediately','In this use, table means set aside for later.','meaning'),Q(1,'Latin tabula meant…','board or flat surface','drink','a house of worship','The Latin source referred to a flat board or tablet.','word-formation')]);
P('tableland','Tableland combines table + land; it names a broad area of elevated ground with a relatively level surface.',C('tableland.s1','地理','The survey team crossed a dry tableland that rose above the surrounding river plain.','测绘队穿过一片干燥高原地带，它高出周围的河流平原。','high/open tableland; tableland above a plain','名词，指地势较高、顶面相对平坦的大片土地。','the elevated area has a level top.','地理'),M('The tableland was a deep valley below the river plain, with no level high ground.','The tableland rose above the river plain with a broad level surface.','tableland是高而平坦的地貌，不是低于平原的深谷。','meaning'),[Q(1,'A tableland is…','a broad elevated area with a level surface','a low narrow river channel','a piece of table furniture','The compound describes a plateau-like landform.','meaning'),Q(1,'Where was the tableland in the survey?','Above the surrounding river plain','Beneath the river bed','Inside a browser tab','The context contrasts elevated land with the plain.','context'),Q(1,'Which phrase is natural?','a dry tableland above the plain','a tableland underly the plain','tableland of a river into','Above marks the landform’s relative elevation.','collocation'),Q(1,'Tableland combines table with…','land','tab','tale','The compound describes land with a broad flat top.','word-formation')]);
P('tablet','Tablet is a diminutive of table, from Latin tabula, “flat board”; it can mean a solid dose of medicine, a touch-screen computer, or a flat inscribed slab.',[C('tablet.s1','药物','Take one tablet with water after breakfast, following the label’s instructions.','按标签说明，早餐后用水服一片药。','a pain-relief tablet; take/swallow a tablet','名词，指吞服的一小块固体药物。','a single dose is taken with water.','药物'),C('tablet.s2','电子设备','She used a tablet to mark up the digital map during the site visit.','现场勘察时，她用平板电脑在电子地图上做标注。','a tablet computer; use a tablet','名词，指通过触摸屏操作的平板计算机。','the touchscreen device displays a map.','电子设备'),C('tablet.s3','历史','The archaeologist photographed a clay tablet bearing a merchant’s account.','考古学家拍摄了一块写有商人账目的泥板。','a stone/clay tablet; write on a tablet','名词，指写有或刻有文字的扁平石片、泥板。','the flat surface preserves written marks.','历史')],M('She swallowed a tablet, a large touch-screen computer, with water after breakfast.','She swallowed one small medicine tablet with water after breakfast.','服用药片的tablet不是电子平板电脑。','confusable'),[Q(1,'Take one tablet after breakfast means take…','one small solid dose of medicine','a computer device','a clay writing slab','Sense 1 is the medicine meaning.','meaning'),Q(2,'She marked up a map on a tablet means she used…','a touch-screen computer','a pill','a stone inscription','Sense 2 is the electronic device.','context'),Q(3,'An inscribed clay tablet is…','a flat piece bearing writing','a paper folder tab','a food bill','Sense 3 is the ancient writing surface.','meaning'),Q(1,'Which phrase is natural for medicine?','swallow a tablet with water','swallow a tablet computer with water','swallow a tablet on waterly','With water describes how the dose is taken.','collocation')]);
P('tabletop','Tabletop combines table + top; it means the flat upper surface of a table, considered separately from its legs or frame.',C('tabletop.s1','家具','A hot pan left a pale ring on the wooden tabletop.','一口热锅在木桌面上留下了一圈浅色印记。','wooden/glass tabletop; wipe the tabletop','名词，指桌子的上平面，不包括桌腿。','the mark is on the flat upper surface.','家具'),M('The scratch was on the tabletop, the table’s four legs beneath the surface.','The scratch was on the tabletop, the flat upper surface of the table.','tabletop指桌面，不是桌腿。','meaning'),[Q(1,'The tabletop is…','the upper flat surface of a table','the table’s legs','a meal served on plates','That is the noun’s definition.','meaning'),Q(1,'Where did the hot pan leave a ring?','On the wooden upper surface','On a browser tab','Under the floor','The context specifies the tabletop.','context'),Q(1,'Which phrase is natural?','wipe the tabletop clean','tabletoply wipe the clean','wipe the table legs tabletop','Tabletop is the surface being wiped.','grammar'),Q(1,'Tabletop combines table with…','top','land','ware','The compound identifies the top surface.','word-formation')]);
P('tableware','Tableware combines table + ware, “goods or articles”; it means dishes, cups, and often cutlery used for serving or eating food.',C('tableware.s1','餐饮','The hotel hired extra tableware for the banquet, including plates, cups, and serving forks.','酒店为宴会租了更多餐具，包括盘子、杯子和分餐叉。','ceramic/tableware; set the table with tableware','名词，常作不可数集合名词，指用餐的盘、碗、杯等器具。','the items are used to serve and eat food.','餐饮'),M('The banquet tableware included plates and cups, but no items used for serving or eating food.','The banquet tableware included plates, cups, and forks for serving food.','tableware指餐桌用具，不能排除所有用于用餐的器具。','meaning'),[Q(1,'Tableware includes…','plates, bowls, cups, and often cutlery','only a dining table','a written summary','That is the collective noun’s scope.','meaning'),Q(1,'What did the hotel hire?','Plates, cups, and serving forks','A tablet computer','A tag for each guest only','The context names examples of tableware.','context'),Q(1,'Which sentence is natural?','The tableware is ready for dinner.','The tablewares are ready for dinner.','Tableware are ready for dinner.','Tableware is usually an uncountable collective noun.','grammar'),Q(1,'In tableware, ware means…','goods or articles','a table’s upper surface','a small label','Ware names the articles used for dining.','word-formation')]);
P('tabloid','Tabloid was coined in 1884 as a trade name for a compressed medicine, a hybrid of tablet and -oid; the newspaper sense followed the idea of condensed material, and the word can also describe oversimplified coverage.',[C('tabloid.s1','媒体','The commuter bought a tabloid with short articles and celebrity photographs.','通勤者买了一份文章短、名人照片多的小开本报纸。','a daily tabloid; tabloid newspaper','名词，指版面较小、文章短、图片多的报纸，常报道名人或轰动新闻。','compact paper uses brief stories and many images.','媒体'),C('tabloid.s2','概述','The documentary offers a tabloid version of the dispute, omitting the legal detail.','这部纪录片对争端给出了过度简化的说法，省略了法律细节。','a tabloid version/account; tabloid treatment','名词，也指对复杂事情过分简单化的叙述。','important qualifications are left out.','概述')],M('The report gave a tabloid version of the dispute by carefully explaining every qualification and legal detail.','The report gave a tabloid version by reducing the dispute to a few oversimplified claims.','tabloid version在此表示过度简化，不是完整细致的分析。','meaning'),[Q(1,'A tabloid newspaper is typically…','small-format, with short stories and many pictures','a large scholarly journal','a set of medical signs','Sense 1 is the newspaper meaning.','meaning'),Q(2,'A tabloid version of an issue…','oversimplifies it and leaves out detail','contains every qualification','is always a neutral full analysis','Sense 2 is the figurative account.','context'),Q(1,'Which phrase is natural?','a tabloid newspaper','a tabloidly newspaper','a tablet newspaper of','Tabloid is an adjective or noun modifier for newspaper.','grammar'),Q(1,'The first tabloid was named for its compact…','tablet-like form','synagogue-like shape','system of rows','The early coinage referred to a compact tablet form.','word-formation')]);
P('taboo','Taboo entered English from Tongan tapu, “forbidden or sacred”; it names a strong social/religious prohibition and describes what custom forbids.',[C('taboo.s1','社会','In that community, discussing a relative’s debt remains a taboo.','在那个社区，谈论亲属的债务仍然是禁忌。','a social/religious taboo; break a taboo','名词，指社会或宗教中强烈禁止某种行为或话题的规矩。','custom discourages open discussion.','社会'),C('taboo.s2','话题','The subject of workplace harassment was once taboo at the company, but staff now discuss it openly.','职场骚扰这个话题过去在公司里是禁忌，但员工现在会公开讨论。','a taboo subject; be taboo to discuss','形容词，指因习俗而禁止或不宜公开谈论的。','the topic was formerly silenced by custom.','话题')],M('The subject was taboo at work, so employees openly discussed it at every meeting without hesitation.','The subject was taboo at work, so employees avoided discussing it openly.','taboo话题通常被禁止或不宜公开谈论，与毫无顾忌地讨论相反。','meaning'),[Q(1,'A social taboo is…','a strong rule against an action or topic','a routine table listing','a highly skilled person','That is the noun sense.','meaning'),Q(2,'A taboo subject is…','forbidden or too shocking to discuss openly','required at every meeting','a kind of spreadsheet','Sense 2 is the adjective.','context'),Q(1,'Which phrase is natural?','break a taboo','break tabooing a','taboo of break','Break is a common verb with taboo.','collocation'),Q(1,'Taboo entered English from Tongan…','tapu, “forbidden or sacred”','tabula, “board”','tithenai, “put”','The Tongan source supplied the word’s prohibition sense.','word-formation')]);
P('tabulate','Tabulate comes from Latin tabula, “board or table”; it means arrange figures or facts in rows and columns.',C('tabulate.s1','数据','The analyst tabulated survey answers by age group before calculating the totals.','分析师先按年龄组把问卷答案制成表格，再计算总数。','tabulate results/data; tabulate by category','动词，指把数字或事实按行列整理出来。','responses are sorted into a table.','数据'),M('The analyst tabulated the survey by scattering responses randomly without sorting or listing them.','The analyst tabulated the survey by arranging responses in rows by age group.','tabulate表示按行列整理数据，随机散放不是制表。','meaning'),[Q(1,'To tabulate survey answers is to…','arrange them in a table','turn them into a taboo','say them aloud without recording','That is the verb’s meaning.','meaning'),Q(1,'How did the analyst group the answers?','By age group','By table height','By the order of the interviewer’s shoes','The context identifies the category used for tabulation.','context'),Q(1,'Which construction is natural?','tabulate results by age','tabulate results to age byly','tabulation the results age','By introduces the grouping criterion.','grammar'),Q(1,'Tabulate comes from Latin tabula, meaning…','board or table','drink','time','The Latin source named a flat surface used for arranging information.','word-formation')]);
P('tacit','Tacit comes from Latin tacitus, “silent,” the past participle of tacere, “be silent”; it describes something understood or accepted without being stated.',C('tacit.s1','沟通','The neighbors reached a tacit agreement to keep the shared path clear.','邻居们达成了默契，同意保持共用小路畅通。','tacit agreement/approval; tacit understanding','形容词，指虽未公开说出却被默认或理解的。','no formal words are needed for the shared expectation.','沟通'),M('They made a tacit agreement by signing and reading every term aloud in a public meeting.','They made a tacit agreement without stating it openly.','tacit agreement是未明说的默契，不是公开逐条宣读并签字。','meaning'),[Q(1,'A tacit agreement is…','understood or accepted without being openly stated','written in full and read aloud','a legal tablet','That is the adjective’s meaning.','meaning'),Q(1,'What did the neighbors agree to do?','Keep the shared path clear','Close the synagogue','Change the syntax of a sentence','The context gives the unspoken shared expectation.','context'),Q(1,'Which phrase is natural?','tacit approval of the plan','tacitly approval of plan','a tacit to approve','Tacit is an adjective modifying approval.','grammar'),Q(1,'Latin tacitus meant…','silent','board','to put together','The Latin source connects tacit with what is not spoken.','word-formation')]);
P('tack','Tack has several histories: the small nail is recorded in Middle English, with deeper origin uncertain; the “approach” sense is associated with a sailing vessel’s course.',[C('tack.s1','工具','She fixed the notice to the corkboard with a brass tack.','她用一枚黄铜图钉把通知固定在软木板上。','a drawing/thumb tack; tack something up','名词，指钉头宽而扁的短钉。','the tack holds paper to a board.','工具'),C('tack.s2','策略','After the first campaign failed, the team took a different tack on costs.','第一次行动失败后，团队换了一种处理成本的策略。','take a different tack; change tack','名词，比喻处理问题时所选的方式或路线。','the approach changes after failure.','策略'),C('tack.s3','固定','She tacked a reminder to the door so nobody would miss it.','她把一张提醒便条钉在门上，免得有人漏看。','tack a note to a board; tack fabric','动词，指用图钉或疏缝临时固定，也可附加某物。','a paper is fastened to the door.','固定')],M('She fixed the paper notice with a tack, a long cord with no hard point or head.','She fixed the notice to the board with a short, flat-headed tack.','tack此处是短小的尖钉，不是绳子。','meaning'),[Q(1,'A brass tack on a corkboard is…','a short nail with a wide flat head','a piece of clothing fabric','a scheduling system','Sense 1 names the fastener.','meaning'),Q(2,'Taking a different tack on costs means…','choosing a different approach','sailing the same route unchanged','adding a flat nail','Sense 2 is a figurative method.','context'),Q(3,'She tacked a reminder to the door means she…','fastened it there with a tack','removed it from the door','read it aloud','Sense 3 is the verb meaning fasten.','meaning'),Q(1,'Which phrase is natural?','take a different tack','take a different tacked','take tack different a','The set phrase means adopt a different approach.','collocation')]);
P('tackle','Tackle likely came through Dutch for equipment or rigging; English uses it for dealing with a problem, stopping a player, or the equipment/action involved.',[C('tackle.s1','问题','The council formed a task force to tackle illegal dumping near the river.','市议会成立工作组，处理河边非法倾倒垃圾的问题。','tackle a problem/issue; tackle something head-on','动词，指认真着手处理问题。','a task force addresses the problem directly.','问题'),C('tackle.s2','体育','The defender tackled the forward just outside the penalty area.','后卫在禁区外刚好拦截住了前锋。','tackle an opponent; make a tackle','动词，指在运动中阻拦或抢截持球队员。','one player stops an opponent with the ball.','体育'),C('tackle.s3','器材','Fishing tackle filled two waterproof boxes in the boat.','船上的两个防水箱装满了钓鱼用具。','fishing/climbing tackle; tackle box','名词，指某项工作或运动所需的器具；也可指一次阻截。','equipment is stored for fishing.','器材')],M('The city tackled illegal dumping by leaving every reported waste pile untouched.','The city tackled illegal dumping by investigating reports and removing the waste.','tackle问题表示认真处理，放任不管与之相反。','meaning'),[Q(1,'To tackle illegal dumping is to…','make a serious effort to deal with it','ignore it entirely','summarize it in a table','Sense 1 concerns addressing a problem.','meaning'),Q(2,'The defender tackled the forward means the defender…','stopped or tried to take the ball from him','hired him as a worker','gave him fishing gear','Sense 2 is the sports action.','context'),Q(3,'Fishing tackle is…','equipment used for fishing','a social skill','a table’s upper surface','Sense 3 names equipment.','meaning'),Q(1,'Which phrase is natural?','tackle the problem head-on','tackle to the problem head-only','tackling problem with head','Tackle can take the problem directly as its object.','collocation')]);
P('tact','Tact came through French tact from Latin tactus, “touch,” from tangere, “touch”; it is the skill of dealing with people without causing offense.',[C('tact.s1','交往','She handled the complaint with tact, acknowledging the delay without blaming the customer.','她处理投诉时很得体，承认了延误，却没有责怪顾客。','handle a matter with tact; use tact','名词，指说话做事能避免冒犯他人的分寸感。','careful wording addresses the issue respectfully.','交往'),C('tact.s2','体谅','A little tact would have helped him notice how embarrassed the new employee felt.','要是他多体谅一点，就会注意到新员工有多尴尬。','show/lack tact; tact in a difficult moment','名词，也指在难堪时顾及他人感受的体贴。','the speaker recognizes another person’s feelings.','体谅')],M('She handled the complaint with tact by mocking the customer in front of the entire staff.','She handled the complaint with tact by listening privately and responding respectfully.','tact要求避免冒犯，公开嘲笑顾客与之相反。','meaning'),[Q(1,'Handling a complaint with tact means…','responding without offending the person','ignoring the complaint','using a touch-screen tablet','Sense 1 is interpersonal skill.','meaning'),Q(2,'Why would tact help with the new employee?','It helps notice and consider embarrassment','It makes the employee speak more loudly','It improves a filing system','Sense 2 concerns sensitivity to feelings.','context'),Q(1,'Which phrase is natural?','handle criticism with tact','handle tactly criticism with','a tact to criticismly','With tact is the standard phrase.','collocation'),Q(1,'Latin tactus, source of tact, meant…','touch','arrange','take','The historical source links tact with a figurative “touch” in social dealings.','word-formation')]);
P('tactful','Tactful is formed from tact + -ful; it describes considerate speech or behavior that avoids offense, or skillful handling of people.',[C('tactful.s1','说话','She gave a tactful reply to the awkward question about the budget.','面对有关预算的尴尬问题，她给出了得体的回答。','a tactful reply/remark; be tactful about','形容词，指说话有分寸、避免冒犯。','the reply answers without embarrassing anyone.','说话'),C('tactful.s2','体谅','He was tactful about the delay and recognized that the team had been understaffed.','他体谅进度延误的原因，注意到团队人手不足。','tactful about a problem; tactful handling','形容词，也指在难处境中顾及他人感受。','the explanation is sensitive to the team’s situation.','体谅'),C('tactful.s3','调停','Her tactful handling kept both sides talking until they agreed on a schedule.','她巧妙周旋，让双方一直谈到就日程达成一致。','tactful handling/intervention; act tactfully','形容词，也指冷静而巧妙地处理人际关系。','she keeps communication open and resolves tension.','调停')],M('She gave a tactful reply by repeating the embarrassing question loudly in front of everyone.','She gave a tactful reply that answered the question without humiliating anyone.','tactful的回答会避免使人难堪，不会放大尴尬。','meaning'),[Q(1,'A tactful reply is…','careful not to offend or embarrass','intentionally insulting','a device that synchronizes a flash','Sense 1 concerns considerate wording.','meaning'),Q(2,'How was he tactful about the delay?','He considered the team’s lack of staff','He blamed one person publicly','He refused to discuss the cause','Sense 2 is sensitivity to others’ circumstances.','context'),Q(3,'Tactful handling that keeps both sides talking is…','skillful management of people','a refusal to listen','a database system','Sense 3 concerns managing contact between people.','meaning'),Q(1,'Which phrase is natural?','a tactful response to criticism','a tactfully response criticism to','a tactfulness response at','Tactful is the adjective modifying response.','grammar')]);
P('tactic','Tactic comes through French from Greek taktikos, “of arranging,” related to tassein, “arrange”; it is a specific method for an aim or a way of influencing people.',[C('tactic.s1','策略','Delaying the vote was a tactic to give the committee more time to review the evidence.','推迟表决是一种策略，目的是给委员会更多时间审查证据。','a tactic for/against; use/adopt a tactic','名词，指为达到目标选择的具体方法。','the delay serves a planned aim.','策略'),C('tactic.s2','人际','The salesperson used a familiar tactic: offer a discount only if the customer signed that day.','销售员用了常见手法：只有顾客当天签约才给折扣。','a negotiating/sales tactic; use a tactic on someone','名词，也可指为从别人那里得到想要结果而采取的做法。','conditional offer pressures a customer.','人际')],M('Delaying the vote was a tactic to give the committee less review time, but the delay extended its review by two weeks.','Delaying the vote was a tactic to give the committee more time to review evidence.','战术的目的与造成的结果在原句中自相矛盾。','meaning'),[Q(1,'A tactic to delay a vote is…','a specific method chosen to reach an aim','a natural ability','a meeting of experts','Sense 1 is the planned method.','meaning'),Q(2,'The salesperson’s discount tactic is…','a method used to influence a customer','a medical sign','a table surface','Sense 2 concerns behavior toward another person.','context'),Q(1,'Which phrase is natural?','a tactic for reducing delays','a tactically for delay','a tactic to reduction delays at','For introduces the goal of the method.','grammar'),Q(1,'Greek taktikos was related to tassein, meaning…','arrange','touch','drink','The source idea concerns arranging or organizing methods.','word-formation')]);
P('tactics','Tactics is the plural of tactic; it names chosen methods for winning a contest or clever ways of dealing with people.',[C('tactics.s1','比赛','The coach changed the team’s tactics at halftime to exploit the open left side.','教练在中场休息时改变战术，以利用左路的空当。','change/adopt tactics; defensive tactics','名词复数，指为赢得比赛、战役或竞争而选的方法。','the team alters its plan to use an opening.','比赛'),C('tactics.s2','人际','Her office tactics helped her secure a promotion without undermining her colleagues.','她的职场手段帮助她获得晋升，同时没有损害同事利益。','negotiating/office tactics; use tactics to get something','名词复数，也指为从他人处达到目的而采取的巧妙做法。','the person navigates workplace relationships.','人际')],M('The coach changed tactics at halftime by refusing to adjust the plan despite the open flank.','The coach changed tactics at halftime to attack through the open flank.','改变战术意味着调整做法，原句却说拒绝调整。','meaning'),[Q(1,'A team’s tactics are…','methods chosen to win a match','the players’ natural talents only','the stadium seating plan','Sense 1 is the competition strategy meaning.','meaning'),Q(2,'Office tactics are…','ways of dealing with people to reach a goal','a set of sports equipment','rules for chromosome pairing','Sense 2 concerns interpersonal methods.','context'),Q(1,'Which phrase is natural?','change tactics at halftime','change tacticss at halftime','tactics change to halftimely','Tactics is the plural noun used for a set of methods.','plural'),Q(1,'Tactics is the plural form of…','tactic','tact','tactile','The singular form is tactic.','plural')]);
P('tactile','Tactile comes from Latin tactilis, from tangere, “touch”; it means related to or perceived through the sense of touch.',C('tactile.s1','感官','The museum made a tactile map so visitors with limited vision could trace the streets with their fingers.','博物馆制作了触觉地图，让视力有限的访客可以用手指摸索街道。','tactile map/feedback/sensation; tactile surface','形容词，指与触摸有关或通过触摸感知的。','visitors use their hands to perceive the map.','感官'),M('The tactile map could only be understood by smell and gave visitors no surface to touch.','The tactile map let visitors feel the raised streets with their fingers.','tactile指通过触摸感知，不能只靠嗅觉。','meaning'),[Q(1,'A tactile map is designed to be…','perceived by touch','heard through music only','read only as a synopsis','That is the adjective’s sense.','meaning'),Q(1,'How did visitors use the map?','They traced raised streets with their fingers','They smelled the paper','They changed the map’s syntax','The context shows touch as the means of perception.','context'),Q(1,'Which phrase is natural?','tactile feedback','tactically feedback','a tactile of feedback','Tactile is the adjective modifying feedback.','grammar'),Q(1,'Latin tactilis is related to tangere, “…”','touch','arrange','put together','The Latin root directly names the sense involved.','word-formation')]);
P('tadpole','Tadpole combines an old word for toad with pole, “head”; it is the aquatic young stage of a frog or toad before its legs are fully developed.',C('tadpole.s1','动物','The pond was crowded with tadpoles that still had tails and gills.','池塘里挤满了仍长着尾巴和鳃的蝌蚪。','frog/toad tadpole; tadpole stage','名词，指蛙或蟾蜍的水生幼体，长有尾巴和鳃、尚未发育出腿。','the young amphibians are in their aquatic stage.','动物'),M('The tadpole had fully developed legs and lived on land as an adult frog.','The tadpole still had a tail and gills and had not yet developed its legs.','tadpole是长腿之前的水生幼体阶段。','meaning'),[Q(1,'A tadpole is…','a young aquatic frog or toad with a tail and gills','an adult frog that lives only on land','a touch-screen device','That is the animal’s early life stage.','meaning'),Q(1,'What could still be seen in the pond?','Tails and gills on the tadpoles','Adult frogs with no tails only','A group of tableware','The context describes their undeveloped stage.','context'),Q(1,'Which phrase is natural?','a tadpole develops legs','a tadpole develops leggedly','a tadpole is leg before','Develops legs describes the change during growth.','grammar'),Q(1,'In tadpole, pole historically referred to a…','head','tail','gill','The compound was formed as “toad-head.”','word-formation')]);
P('tag','Tag has an uncertain early origin; it names an attached label, a descriptive name, or the act of labeling or adding a remark.',[C('tag.s1','标签','Each suitcase had a paper tag showing the passenger’s name and flight number.','每只行李箱上都有一张纸标签，写着乘客姓名和航班号。','price/name tag; attach a tag','名词，指附在物品上提供信息的小纸片、塑料片或金属片。','the label identifies the bag.','标签'),C('tag.s2','称呼','He dislikes the tag of “local expert” because he has only worked there for one year.','他不喜欢“本地专家”这个称号，因为他在那里工作才一年。','the tag of expert; label/tag someone as','名词，也指用于描述某人或群体的称呼。','the phrase categorizes the person.','称呼'),C('tag.s3','标记','The staff tagged each box before sending it to the warehouse.','工作人员把每个箱子贴上标签后再送到仓库。','tag a bag/item; tag someone in a post','动词，指贴上标签，也可指补上一句或跟着某人。','items are labeled before shipment.','标记')],M('The suitcase tag showed the passenger’s name, but it was not attached to or associated with the bag.','The suitcase carried a tag showing the passenger’s name.','tag此处是附在行李上的标记。','meaning'),[Q(1,'A paper tag on a suitcase is…','a small attached label with information','a medical symptom','a set of tactics','Sense 1 is the label meaning.','meaning'),Q(2,'The tag of “local expert” is…','a descriptive label or title','a paper price label only','a verb meaning to remove','Sense 2 is the figurative name.','context'),Q(3,'The staff tagged each box means they…','attached or added identifying labels','opened a browser tab','took the boxes apart','Sense 3 is the verb meaning label.','meaning'),Q(1,'Which phrase is natural?','a tag on the suitcase','a tag at suitcasely','a suitcase tag of on','On identifies the surface carrying the label.','collocation')]);
P('tail','Tail comes from Old English tægel; it means an animal’s rear appendage, the back end of something, or secretly follow someone.',[C('tail.s1','动物','The dog wagged its tail when the children returned from school.','孩子们放学回来时，狗摇起了尾巴。','wag a tail; a long/bushy tail','名词，指动物身体后方伸出的部分。','the dog moves its rear appendage.','动物'),C('tail.s2','末端','Our seats were at the tail of the queue, farthest from the ticket window.','我们的座位排在队伍末尾，离售票窗口最远。','tail end; at the tail of a line','名词，也指细长事物的后部或末端。','the people stand at the last part of the line.','末端'),C('tail.s3','跟踪','An investigator tailed the van from the depot without being noticed.','调查员悄悄跟踪那辆面包车离开车站，没有被发现。','tail a suspect/car; be tailed by police','动词，指秘密跟随某人以便监视。','the observer follows the vehicle secretly.','跟踪')],M('The investigator tailed the van by driving openly in front of it and announcing every turn.','The investigator tailed the van from behind without attracting attention.','tail作动词表示秘密跟踪，公开在前方带路与之相反。','meaning'),[Q(1,'The dog wagged its tail means it moved…','the appendage at the rear of its body','the front of its nose','the end of a queue','Sense 1 is the animal meaning.','meaning'),Q(2,'At the tail of the queue means…','at its back or last part','at its front','following a suspect secretly','Sense 2 is the end meaning.','context'),Q(3,'An investigator tailed a van means the investigator…','followed it secretly','repaired its rear door','waited at the end of a line','Sense 3 is the verb meaning surveil by following.','meaning'),Q(1,'Which phrase is natural?','tail a suspect through the station','tail to a suspect through','tailing a suspect throughly','Tail takes the person or vehicle followed as its object.','grammar')]);
P('tailor','Tailor came through Old French tailleor, “cutter,” from taillier, “cut”; it names a clothing maker and can mean adapt something to suit a person or purpose.',[C('tailor.s1','职业','The tailor shortened the sleeves of my coat while I waited.','我等候时，裁缝把大衣袖子改短了。','a skilled tailor; take something to a tailor','名词，指缝制或修改合身衣服的人。','a clothing professional alters the garment.','职业'),C('tailor.s2','适配','The course is tailored to beginners who have never used design software.','这门课程专为从未使用过设计软件的初学者量身设计。','tailor something to/for a need; tailor a plan','动词，指调整某物以适合某人或某种目的。','course content is adapted to learner needs.','适配')],M('The tailor tailored the course to beginners by using advanced lessons designed only for experts.','The tailor tailored the course to beginners by starting with basic design skills.','tailor something to a group means adapt it to their level, not deliberately exclude them.','meaning'),[Q(1,'A tailor is…','a person who makes or alters clothes','a person who follows someone secretly','a seller of tabloids','Sense 1 is the occupation.','meaning'),Q(2,'A course tailored to beginners is…','adapted for people with little experience','unchanged for every learner','a medical device','Sense 2 is the verb meaning customize.','context'),Q(1,'Which construction is correct?','tailor a plan to the client’s needs','tailor a plan at client needsly','tailor to a plan the needs','To introduces the person or purpose being accommodated.','grammar'),Q(1,'Tailor came through Old French tailleor, related to a verb meaning…','cut','touch','synchronize','The original occupation cut cloth to make garments.','word-formation')]);
P('tailored','Tailored is the past participle of tailor; it means specially adapted for a person or purpose, or fitted neatly to the body.',[C('tailored.s1','适配','The training guide was tailored to small firms with no in-house legal team.','这份培训指南专为没有内部法务团队的小企业调整过。','tailored to/for a group; tailor-made service','形容词，指根据某人或某目的专门制作或调整。','the guide is adapted to a defined audience.','适配'),C('tailored.s2','服装','He wore a tailored jacket that fit his shoulders without pulling at the seams.','他穿着一件剪裁合身的夹克，肩部服帖，接缝也没有绷紧。','a tailored suit/jacket; neatly tailored','形容词，指经过剪裁修改、贴合穿着者身材的衣服。','the garment fits the wearer precisely.','服装')],M('The tailored jacket hung loosely at the shoulders and was never adjusted to fit its wearer.','The tailored jacket was adjusted to fit neatly at the shoulders.','tailored服装指剪裁合身，不是未经修改的宽松衣服。','meaning'),[Q(1,'A guide tailored to small firms is…','specially adapted for those firms','a standard version regardless of audience','a jacket fitted to a body','Sense 1 is customization for a purpose.','meaning'),Q(2,'A tailored jacket…','has been cut or adjusted to fit well','is intentionally too large','is a medical tablet','Sense 2 is the clothing fit sense.','context'),Q(1,'Which phrase is natural?','a service tailored to local needs','a tailoredly service to needs','tailored at local need by','To introduces the needs the service is adapted for.','grammar'),Q(1,'Tailored is the past participle of…','tailor','tail','tact','It comes from the verb meaning make or adapt.','verb-form')]);
P('taint','Taint came through Old French teint, from teindre, “dye,” ultimately Latin tingere, “dip or color”; it means contaminate or damage a reputation, or the resulting mark.',[C('taint.s1','名誉','The scandal left a taint of doubt on the board’s reputation for honesty.','丑闻给董事会诚实可靠的声誉留下了疑点污痕。','a taint of suspicion; leave a taint on','名词，指不诚实或受损后留下的污点或不良印象。','the reputation is marked by suspicion.','名誉'),C('taint.s2','污染','The chemical spill tainted the water supply for several weeks.','化学品泄漏使供水受到污染，持续了数周。','taint food/water; be tainted with','动词，指使食物、空气或其他物质变得不洁或不安全。','the substance contaminates the water.','污染'),C('taint.s3','声誉','The false accusation tainted her reputation for careful research.','这项虚假指控损害了她认真研究的名声。','taint someone’s reputation; tainted evidence','动词，也指损害某人的好名声或事物的良好品质。','an accusation harms public trust.','声誉')],M('The spill tainted the water supply, making the water cleaner and safer to drink.','The spill tainted the water supply, making it unsafe until tested and treated.','taint表示污染、使不安全，不是净化。','meaning'),[Q(1,'A taint of doubt on a reputation is…','a mark that damages how people view it','a sign of excellent health','a row in a data table','Sense 1 names a damaging trace.','meaning'),Q(2,'The spill tainted the water means it…','made the supply dirty or unsafe','made it safer to drink','organized it into rows','Sense 2 is contamination.','context'),Q(3,'A false accusation tainted her reputation means it…','damaged her good name','made her reputation more trustworthy','repaired the water pipes','Sense 3 is damage to standing or quality.','meaning'),Q(1,'Latin tingere, an ancestor of taint, meant…','dip or color','arrange a system','take a route','The historical source referred to coloring or dipping.','word-formation')]);
P('take','Take comes from Old Norse taka, “take, grasp”; it has many uses, including carry, accept, require time, travel by, and interpret.',[C('take.s1','携带','Take this sealed envelope to the records office before noon.','中午前把这只封好的信封送到档案办公室。','take something to a place; take someone with you','动词，指把某物或某人带到另一处。','the envelope is moved to a destination.','携带'),C('take.s2','接受','Lena took the job after comparing its hours with her family schedule.','莉娜比较了工作时间与家庭安排后接受了这份工作。','take a job/offer/advice; take something offered','动词，指接受别人提供或现成的东西。','the offer is accepted.','接受'),C('take.s3','耗费','The repair will take about three hours if the replacement part arrives on time.','如果替换零件按时到货，维修大约需要三小时。','take time/money/effort; it takes someone time to do','动词，指某事需要一定时间、金钱或力气。','the repair requires a stated duration.','耗费'),C('take.s4','交通','We took the bus to the clinic because the road was icy.','因为道路结冰，我们乘公共汽车去了诊所。','take a bus/train/route; take the road to','动词，指乘坐交通工具或走某条路线。','the bus is the chosen transport.','交通'),C('take.s5','理解','I took his brief reply as agreement, but he meant only that he had heard me.','我把他简短的答复理解为同意，但他只是说听到了。','take something as a sign/joke; take a remark to mean','动词，指以某种方式理解话语或情况。','the speaker interprets a reply.','理解')],M('I took the bus to the clinic by walking the entire distance and never boarding it.','I took the bus to the clinic because the road was icy.','take a bus表示乘坐公交车，不是全程步行。','meaning'),[Q(1,'Take this envelope to the office means…','carry it there','accept a job','interpret it as a joke','Sense 1 is carrying to a place.','meaning'),Q(2,'Lena took the job means she…','accepted the offered position','spent three hours on it','rode a bus to it','Sense 2 is accepting an offer.','context'),Q(3,'The repair will take three hours means it…','requires that amount of time','will travel by bus','will be understood as a joke','Sense 3 describes required duration.','meaning'),Q(5,'I took his reply as agreement means I…','interpreted it to mean agreement','carried his reply to the office','accepted a job','Sense 5 concerns how the words were understood.','meaning')]);
P('take action','Take action combines take with action, from Latin actio, “a doing”; it means begin doing something to address a problem or reach a goal.',C('take action.s1','应对','The council promised to take action against noise from late-night construction.','市议会承诺采取行动，处理深夜施工噪声问题。','take action on/against; prompt action','短语，指开始采取措施处理问题或实现目标。','the council moves beyond discussion toward measures.','应对'),M('The council took action against the noise by discussing it for months but refusing to make any change.','The council took action against the noise by enforcing limits on construction hours.','take action表示着手处理，长期空谈且不改变措施与之相反。','meaning'),[Q(1,'To take action against noise means to…','start doing something to address it','only talk about it indefinitely','make it louder','The phrase means begin measures to deal with a problem.','meaning'),Q(1,'What did the council promise to address?','Late-night construction noise','A film synopsis','A browser tab','The context names the issue.','context'),Q(1,'Which phrase is natural?','take action against pollution','take action for to pollution','action take pollution againstly','Against introduces the problem being opposed.','collocation'),Q(1,'Action comes from Latin actio, meaning…','a doing or act','a touch','a flat board','The noun names a deed or process of doing.','word-formation')]);
P('take advantage of','Take advantage of combines take with advantage, from Old French avantage; it means make good use of an opportunity or treat someone unfairly for personal gain.',[C('take advantage of.s1','机会','We took advantage of the clear weather to finish painting the outside wall.','我们趁天气晴朗把外墙刷完了。','take advantage of an opportunity/resource; take full advantage of','短语，指利用有利情形、资源或机会。','good weather is used productively.','机会'),C('take advantage of.s2','剥削','The landlord took advantage of the new tenant’s inexperience by charging illegal fees.','房东利用新租客缺乏经验，向其收取非法费用。','take advantage of someone’s trust/weakness','短语，也指为私利不公平地利用某人，尤其是信任自己的人。','the tenant is exploited through inexperience.','剥削')],M('The landlord took advantage of the tenant’s trust by protecting her from every unfair charge.','The landlord took advantage of the tenant’s trust by charging illegal fees.','此处take advantage of表示不公平利用信任，不是保护对方。','meaning'),[Q(1,'They took advantage of clear weather means they…','used the favorable opportunity','made the weather worse','waited until the rain returned','Sense 1 is beneficial use of a situation.','meaning'),Q(2,'A landlord who takes advantage of a tenant…','uses the tenant unfairly for personal gain','helps the tenant avoid every fee','makes a weather forecast','Sense 2 is the exploitative meaning.','context'),Q(1,'Which phrase is correct?','take advantage of an opportunity','take advantage an opportunity ofly','take of advantage the opportunity','Of is required before the thing or person used.','grammar'),Q(1,'Advantage came through Old French avantage, related to…','something favorable or in front','a pipe or tube','a medical faint','The historical source carried the idea of a favorable position.','word-formation')]);
P('take after','Take after is a phrasal verb whose particle after marks resemblance; it means resemble a relative in appearance or habits.',C('take after.s1','亲属','Nina takes after her mother in the way she laughs and tells stories.','妮娜在笑声和讲故事的方式上都像她母亲。','take after a parent/relative; take after someone in a trait','短语动词，指外貌或习惯像某位亲属。','two family members share recognizable traits.','亲属'),M('Nina takes after her mother because she looks and behaves completely unlike anyone in her family.','Nina takes after her mother in her laugh and storytelling.','take after表示与亲属相像，原句所说的完全不像与之矛盾。','meaning'),[Q(1,'Nina takes after her mother means Nina…','resembles her in some ways','works after her mother’s shift','takes her mother to a clinic','That is the phrasal verb’s family-resemblance sense.','meaning'),Q(1,'What traits do they share?','Their laugh and storytelling','Their height and tableware','Their work schedule only','The context specifies habits in which Nina resembles her mother.','context'),Q(1,'Which phrase is natural?','take after your father in appearance','take after to your father appearance','take your father afterly in appearance','After is the particle used in this idiom.','grammar'),Q(1,'In this idiom, after contributes the idea of…','resemblance or following a family pattern','removing a layer','a methodical process','The phrase extends “following after” to similarity.','word-formation')]);
P('take apart','Take apart combines take with apart; it means separate an object into pieces or examine an argument closely to expose weaknesses.',[C('take apart.s1','拆卸','Ravi took the clock apart to clean the gears and replace a worn spring.','拉维把钟拆开，清理齿轮并更换磨损的弹簧。','take a machine apart; take apart carefully','短语动词，指把机器或物品拆成各个部分。','the clock is disassembled for repair.','拆卸'),C('take apart.s2','分析','The reviewer took the proposal apart line by line and showed where its numbers failed.','评论者逐行剖析了提案，指出其中数据的问题。','take an argument/plan apart; take apart critically','短语动词，也指逐项分析论点或计划，指出其弱点。','each claim is examined critically.','分析')],M('Ravi took the clock apart to clean it, but kept every gear sealed inside the untouched case.','Ravi took the clock apart and removed the gears for cleaning.','take a clock apart意味着把它拆开，不能仍将零件封在完整外壳里。','meaning'),[Q(1,'Ravi took the clock apart means he…','separated it into its component pieces','carried it to a different room','summarized its history','Sense 1 is physical disassembly.','meaning'),Q(2,'The reviewer took the proposal apart means the reviewer…','examined it closely to expose weaknesses','built the proposal from parts','accepted every claim without review','Sense 2 is critical analysis.','context'),Q(1,'Which phrase is natural?','take the engine apart','take apart to the engine','take apartly engine','The object can precede the particle in this phrasal verb.','grammar'),Q(1,'Apart contributes the idea of…','separation into parts','movement into a group','simultaneous timing','The particle marks division or analytical separation.','word-formation')]);
P('take away','Take away combines take + away; it means remove or carry something off, and in arithmetic subtract one amount from another.',[C('take away.s1','移除','Please take the empty plates away after the guests finish eating.','客人吃完后，请把空盘子收走。','take something away; take away from a place','短语动词，指从某处移走或离开时带走某物。','the plates are removed from the table.','移除'),C('take away.s2','算术','Take away four from ten and the answer is six.','十减去四，答案是六。','take one number away from another; take away four','短语动词，指从一个数量中减去另一个数量。','the arithmetic result is subtraction.','算术')],M('The server took the empty plates away by leaving them on the table for the next meal.','The server took the empty plates away from the table.','take away表示移走，留在原处与之相反。','meaning'),[Q(1,'Take the empty plates away means…','remove them from the table','add four more plates','take them apart for repair','Sense 1 is the removal meaning.','meaning'),Q(2,'Take away four from ten gives…','six','fourteen','forty','Sense 2 is subtraction.','context'),Q(1,'Which arithmetic phrase is natural?','take two away from nine','take two away to nine','take away from two ninely','From introduces the amount being reduced.','grammar'),Q(1,'In take away, away signals…','movement from a place or amount','movement toward a place','resemblance to a relative','The particle indicates removal or subtraction.','word-formation')]);
P('take back','Take back combines take with back; it means return goods, retract a statement, or make someone remember the past.',[C('take back.s1','退还','They took the faulty printer back to the store and asked for a refund.','他们把有故障的打印机退回商店并要求退款。','take goods back; take something back to a shop','短语动词，指把商品退回商店或把物品还给原主。','the defective item is returned.','退还'),C('take back.s2','收回','After checking the recording, he took back his accusation against the technician.','查看录音后，他收回了对技师的指控。','take back a claim/word; take something back','短语动词，指承认先前说的话不对并予以收回。','the speaker retracts an accusation.','收回'),C('take back.s3','回忆','That familiar song takes me back to the summer I first learned to swim.','那首熟悉的歌让我想起第一次学游泳的那个夏天。','take someone back to a time/place; be taken back','短语动词，指使人想起过去某段时光。','a song prompts a memory.','回忆')],M('He took back his accusation but repeated it at the press conference as a confirmed fact.','He took back his accusation after checking the recording.','take back a statement表示撤回，不是继续公开坚持。','meaning'),[Q(1,'They took the faulty printer back means they…','returned it to the store','opened it in a browser tab','made it work harder','Sense 1 is return of goods.','meaning'),Q(2,'He took back his accusation means he…','retracted what he had said','repeated it as confirmed','took the technician to a shop','Sense 2 is withdrawal of a statement.','context'),Q(3,'The song takes me back to that summer means it…','makes me remember that past time','returns the song to a store','takes me apart','Sense 3 is memory.','meaning'),Q(1,'Which phrase is natural?','take back an accusation','take an accusation back to retractly','take back to an accusation','Take back can take the statement as its object.','grammar')]);
P('take in','Take in combines take + in; depending on context it means absorb, understand, deceive, or provide a person with lodging.',[C('take in.s1','吸收','The dry soil took in the rain quickly after weeks without water.','干旱数周后，干土很快吸收了雨水。','take in water/air; soil takes in moisture','短语动词，指把水、空气等物质吸收到内部。','the substance enters the soil.','吸收'),C('take in.s2','理解','I could not take in all the safety instructions during the first demonstration.','第一次演示时，我没能理解所有安全说明。','take in information; take in what someone says','短语动词，也指理解或注意到新信息。','the instructions are too much to process at once.','理解'),C('take in.s3','欺骗','The fake invoice took in several careful buyers before the scam was reported.','诈骗被举报前，这张假发票骗过了好几位谨慎的买家。','be taken in by a trick; take someone in','短语动词，也指骗得某人相信不真实的事情。','buyers believe the false invoice.','欺骗'),C('take in.s4','住宿','The family took in a visiting student for the semester and gave her a spare room.','这个家庭在整个学期接待了一名来访学生，给她提供了空房间。','take in a guest/student; take someone in','短语动词，还指在自己家中收留或提供住处。','a student is given a place to stay.','住宿')],M('The dry soil took in the rain by remaining completely waterproof and letting no water enter.','The dry soil took in the rain and became moist.','take in水分表示吸收，完全不让水进入与之相反。','meaning'),[Q(1,'The dry soil took in the rain means it…','absorbed the water','rejected all moisture','understood a warning','Sense 1 is physical absorption.','meaning'),Q(2,'I could not take in the instructions means I could not…','understand them fully','carry them to the office','offer someone a room','Sense 2 concerns comprehension.','context'),Q(3,'A fake invoice took in buyers when it…','deceived them into believing it was real','gave them temporary lodging','absorbed their payment automatically','Sense 3 is the deception use.','meaning'),Q(4,'The family took in a visiting student means they…','provided the student with a place to stay','tricked the student','hired the student to take over','Sense 4 is providing lodging.','context')]);
P('take off','Take off uses off to mark removal or departure; it can mean remove clothing, leave the ground, become successful, or take time away from work.',[C('take off.s1','衣物','Please take off your muddy boots before walking across the clean floor.','请在走过干净地板前脱下沾满泥的靴子。','take off a coat/shoes; take your hat off','短语动词，指把衣物或鞋帽从身上脱下。','boots are removed from the body.','衣物'),C('take off.s2','航空','The plane took off ten minutes late because the runway was icy.','由于跑道结冰，飞机晚了十分钟才起飞。','plane/flight take off; take off from a runway','短语动词，指飞机离开地面开始飞行。','the aircraft leaves the runway.','航空'),C('take off.s3','发展','Her online shop took off after a food blogger recommended its handmade bags.','一位美食博主推荐了她的手工包后，网店很快成功起来。','business/career takes off; sales take off','短语动词，指事业、产品或经济很快开始成功。','interest brings rapid early success.','发展'),C('take off.s4','休假','He took off a day from work to attend his daughter’s graduation.','他请了一天假，去参加女儿的毕业典礼。','take a day off; take time off work','短语动词结构中可接时间，指短期不去上班。','a day is spent away from work.','休假')],M('The plane took off from the runway while remaining on the ground throughout the flight.','The plane took off from the runway and began flying.','take off在航空语境中表示离地起飞，不是一直留在地面。','meaning'),[Q(1,'Take off your muddy boots means…','remove them from your feet','put them on','take a day away from work','Sense 1 is removal of clothing.','meaning'),Q(2,'The plane took off means it…','left the ground and began flying','landed on the runway','became a popular shop','Sense 2 is the aviation meaning.','context'),Q(3,'Her shop took off means it…','became successful quickly','closed before opening','removed its shoes','Sense 3 is rapid success.','meaning'),Q(4,'He took off a day from work means he…','did not work that day','started a new job','removed a work uniform only','Sense 4 is time away from work.','context')]);
P('take on','Take on combines take + on; it can mean accept a responsibility, acquire a quality, employ workers, or compete with an opponent.',[C('take on.s1','责任','Mara took on the role of coordinator for the neighborhood project.','玛拉承担了社区项目协调员的职责。','take on a role/task/responsibility; take on work','短语动词，指接受一项工作、责任或承诺。','she accepts a defined duty.','责任'),C('take on.s2','变化','The harbor takes on a golden color at sunset.','日落时，港口呈现出金色。','take on a quality/appearance; take on a new look','短语动词，也指开始具有某种性质或外观。','the light gives the harbor a changed appearance.','变化'),C('take on.s3','雇用','The factory took on fifty workers before the holiday production season.','节日生产季前，工厂雇用了五十名工人。','take on staff/workers; take someone on','短语动词，也指雇用某人。','the business adds employees.','雇用'),C('take on.s4','竞争','The small club took on the league champions without fear.','这家小俱乐部毫不畏惧地迎战了联赛冠军。','take on an opponent/champion; take someone on','短语动词，还指与强劲对手竞争或对付对方。','a weaker side competes against the champion.','竞争')],M('The factory took on fifty workers by dismissing every new employee before their first shift.','The factory took on fifty workers by hiring them for the busy season.','take on staff表示雇用，不是解雇。','meaning'),[Q(1,'Mara took on the coordinator role means she…','accepted the responsibility','quit the project','was hired as a striker','Sense 1 is accepting a duty.','meaning'),Q(2,'The harbor takes on a golden color means it…','begins to have that appearance','hires fifty workers','competes with a champion','Sense 2 is acquiring a quality.','context'),Q(3,'The factory took on fifty workers means it…','employed them','dismissed them','gave them a day off','Sense 3 is hiring.','meaning'),Q(4,'The club took on the champions means it…','competed against them','accepted their job offer','changed color at sunset','Sense 4 is facing an opponent.','context')]);
P('take out','Take out combines take + out; it can mean withdraw or remove something, take someone on an outing, or remove tissue or text.',[C('take out.s1','取出','She took out cash from the account before traveling to the market.','去市场前，她从账户里取了现金。','take money out of an account; take something out','短语动词，指取出物品或从账户提取钱。','money is withdrawn.','取出'),C('take out.s2','邀约','He took his sister out for dinner to celebrate her new job.','他带妹妹出去吃晚饭，庆祝她找到新工作。','take someone out for dinner/a film; take out a guest','短语动词，指带某人去餐馆、电影院等地方。','one person invites another to an outing.','邀约'),C('take out.s3','切除','The surgeon took out the damaged tissue and sent it for testing.','外科医生切除了受损组织，并将其送去检测。','take out tissue/a passage; take something out','短语动词，也指切除身体部分或删掉文本段落。','the tissue is removed from the body.','切除')],M('She took out cash from the account by depositing more money into it.','She took out cash from the account by withdrawing it.','take money out of an account表示取款，不是存款。','meaning'),[Q(1,'She took out cash from the account means she…','withdrew money','deposited money','took a sister to dinner','Sense 1 is withdrawal.','meaning'),Q(2,'He took his sister out for dinner means he…','went somewhere with her as an outing','removed her from a text','hired her for a job','Sense 2 is the social outing use.','context'),Q(3,'The surgeon took out damaged tissue means the surgeon…','removed it from the body','put it into the body','summarized it','Sense 3 is surgical removal.','meaning'),Q(1,'Which phrase is natural?','take money out of an account','take money from account outly','take out to an account money','Out of marks the source from which money is withdrawn.','grammar')]);
P('take over','Take over uses over to mark gaining control; it can mean acquire control of a company/place, seize a vehicle by force, or begin another person’s duties.',[C('take over.s1','控制','The regional group took over the hotel chain after the owners retired.','原业主退休后，地区集团接管了这家连锁酒店。','take over a company/system; take control over','短语动词，指从别人手中取得公司、地点或系统的控制权。','new owners gain control of a business.','控制'),C('take over.s2','劫持','Armed attackers tried to take over the plane during the flight.','飞行途中，武装袭击者试图劫持飞机。','take over a plane/vehicle; attempt a takeover','短语动词，也指用暴力或强制手段控制交通工具。','attackers use force to seize control.','劫持'),C('take over.s3','接班','The evening crew took over monitoring at six when the day team went home.','白班团队回家后，晚班团队在六点接手监控工作。','take over a job/duty; take over from someone','短语动词，还指开始接替别人做一项工作。','one team assumes a continuing duty from another.','接班')],M('The evening crew took over monitoring at six by leaving the controls unattended.','The evening crew took over monitoring at six and continued the watch.','take over此处表示接手工作，不是留下无人看管。','meaning'),[Q(1,'The regional group took over the hotel chain means it…','gained control of the business','sold all its hotels','started a new newspaper','Sense 1 is control of a company.','meaning'),Q(2,'Attackers tried to take over the plane means they tried to…','seize control of the aircraft by force','take a day off','repair the aircraft’s tableware','Sense 2 concerns violent seizure.','context'),Q(3,'The evening crew took over monitoring means it…','began doing the duty after the day crew','stopped all monitoring','bought the hotel chain','Sense 3 is replacing someone in a job.','meaning'),Q(1,'Which phrase is natural?','take over from the day team','take over at the day team fromly','take the day team over froming','From names the person or group being replaced.','collocation')]);
P('take part','Take part combines take with part, from Latin pars, “portion”; the phrase means join an event or activity with other people.',C('take part.s1','参与','All first-year students took part in the discussion about campus transport.','所有一年级学生都参加了关于校园交通的讨论。','take part in an event/activity; take an active part','短语，指与他人一起参加某项活动或事件。','students join a shared discussion.','参与'),M('All first-year students took part in the discussion by staying away and refusing to speak or listen.','All first-year students took part in the discussion by joining the conversation.','take part表示参加，完全缺席与之相反。','meaning'),[Q(1,'To take part in a discussion is to…','join the activity with others','write a synopsis of it only','take over the room','That is the phrase’s meaning.','meaning'),Q(1,'What discussion did the students join?','Campus transport','A tablet medication','A strict synonym','The context identifies the shared activity.','context'),Q(1,'Which construction is correct?','take part in the meeting','take part at the meeting inly','take a part into the meeting','In introduces the event joined.','grammar'),Q(1,'Part comes from Latin pars, meaning…','portion or share','time','a pipe','The phrase suggests sharing in an activity.','word-formation')]);
P('take place','Take place is a phrasal expression meaning happen, often after planning, or be held at a specified time and location.',[C('take place.s1','发生','The power failure took place shortly before the final train left.','停电发生在末班车离开前不久。','an event takes place; take place unexpectedly','短语，指某件事发生。','an incident occurs at a stated time.','发生'),C('take place.s2','举行','The talks will take place in Vienna on the first Monday in May.','会谈将于五月的第一个星期一在维也纳举行。','take place in/at; meeting takes place','短语，也指活动按安排在特定时间地点举行。','the location and date are scheduled.','举行')],M('The talks will take place in Vienna, but the sentence says they were cancelled and never occurred.','The talks will take place in Vienna as scheduled.','take place means happen or be held, not be cancelled.','meaning'),[Q(1,'The power failure took place means it…','happened','was held as a meeting','was taken apart','Sense 1 is occurrence.','meaning'),Q(2,'Talks will take place in Vienna means they…','will be held there','have already been cancelled','will be carried away','Sense 2 describes a scheduled event.','context'),Q(1,'Which phrase is natural?','The ceremony takes place at noon.','The ceremony takes place to noonly.','The ceremony is place taken at noon.','At noon gives the time of the event.','grammar'),Q(1,'Take place is best paraphrased as…','happen or be held','remove something','resemble a relative','The expression is used for events that occur.','meaning')]);
P('take turns','Take turns combines take with turn, from Old English turnian via Latin tornare; it means do an activity in rotation with other people.',C('take turns.s1','轮流','The children took turns reading one paragraph aloud so everyone could practice.','孩子们轮流大声朗读一段，让每个人都有练习机会。','take turns doing something; take turns to speak','短语，指与他人轮换着做同一件事。','each child reads after the previous one.','轮流'),M('The children took turns reading by having one child read every paragraph while the others never participated.','The children took turns reading one paragraph each.','轮流意味着参与者依次替换，而非只有一人一直做。','meaning'),[Q(1,'The children took turns reading means they…','read in rotation','all spoke over one another','left the room','That is the phrase’s meaning.','meaning'),Q(1,'How did everyone get practice?','Each child read a paragraph','One child read every paragraph','No child read aloud','The context explains the rotation.','context'),Q(1,'Which phrase is natural?','take turns answering','take turnly answering','take turns at answeringly','Turns is plural in this set phrase.','grammar'),Q(1,'Turn is historically related to Latin tornare, “…”','turn or shape on a lathe','join together','speak silently','The word’s history is connected with turning.','word-formation')]);
P('take up','Take up combines take + up; it can mean occupy time or space, begin a hobby, accept an offer or place, or resume something.',[C('take up.s1','占用','The display cabinets take up most of the small reception area.','陈列柜占去了小接待区的大部分空间。','take up space/time; take up room','短语动词，指占用一定时间或空间。','the cabinets occupy the available area.','占用'),C('take up.s2','爱好','After retiring, he took up pottery at the community arts center.','退休后，他在社区艺术中心开始学陶艺。','take up a hobby/sport; take up painting','短语动词，也指开始一项新的爱好或活动。','a new leisure activity begins.','爱好'),C('take up.s3','接受','She took up the offer of a place in the research program.','她接受了研究项目提供的名额。','take up an offer/post/place','短语动词，也指接受提议或别人提供的职位、名额。','the offered place is accepted.','接受'),C('take up.s4','继续','When the speaker returned, she took up the story where she had stopped.','演讲者回来后，从刚才停下的地方继续讲述。','take up where someone left off; take up a subject','短语动词，还指接着先前中断的事情继续做。','the interrupted account resumes.','继续')],M('The cabinets took up most of the room by leaving nearly all of the floor space empty.','The cabinets took up most of the room and left little floor space.','take up space表示占据空间，不是腾出空间。','meaning'),[Q(1,'Cabinets take up space means they…','occupy it','make it disappear','begin a hobby','Sense 1 is occupation of area.','meaning'),Q(2,'He took up pottery after retiring means he…','began a new hobby','accepted a job offer','stopped an interrupted story','Sense 2 is starting an activity.','context'),Q(3,'She took up the offer of a place means she…','accepted it','declined it','made the program take longer','Sense 3 concerns accepting an opportunity.','meaning'),Q(4,'She took up the story where she stopped means she…','continued from that point','began an unrelated story','occupied the room','Sense 4 is resuming an activity.','context')]);
P('takeoff','Takeoff is the noun form corresponding to take off; it means an aircraft’s departure from the ground, rapid success, or a humorous imitation.',[C('takeoff.s1','航空','Fog delayed the takeoff until the runway lights became visible.','大雾使起飞延迟，直到跑道灯清晰可见。','plane takeoff; takeoff time','名词，指飞机离开地面开始飞行的动作。','the aircraft waits before leaving the ground.','航空'),C('takeoff.s2','发展','The small company’s takeoff came after its first product reached national stores.','这家小公司在首款产品进入全国商店后迅速发展起来。','economic/career takeoff; a rapid takeoff','名词，指事业、产品或经济突然成功起步。','sales access triggers fast growth.','发展'),C('takeoff.s3','模仿','The comedian’s takeoff of the mayor copied his clipped phrases and careful gestures.','喜剧演员模仿市长时，照搬了他简短的措辞和谨慎的手势。','a takeoff of a person/show; comic takeoff','名词，指对某人说话或行为方式的滑稽模仿。','distinctive mannerisms are copied for humor.','模仿')],M('The company’s takeoff was a rapid commercial success even though sales never began and it closed immediately.','The company’s takeoff followed strong early sales in stores nationwide.','takeoff的成功义指事业迅速起步，与从未销售、立即关闭相反。','meaning'),[Q(1,'A plane’s takeoff is…','the act of leaving the ground','its arrival at the gate','a comic imitation','Sense 1 is aviation.','meaning'),Q(2,'A company’s takeoff means…','a sudden successful start','a complete failure before launch','a plane leaving the ground only','Sense 2 is rapid success.','context'),Q(3,'A comedian’s takeoff of a mayor is…','a humorous imitation of the mayor','a business purchase','a scientific summary','Sense 3 is the parody meaning.','meaning'),Q(1,'Which phrase is natural?','fog delayed the takeoff','fog delayed takeoffing the','a takeoff of runwaying','Takeoff is a noun naming the aircraft’s departure.','grammar')]);
P('takeover','Takeover is formed from take over; it means one company’s purchase of another or the gaining of control of a place, post, or system.',[C('takeover.s1','商业','The board rejected a takeover bid from a rival company that wanted the hotel chain.','董事会拒绝了一家竞争公司收购连锁酒店的报价。','hostile/friendly takeover; takeover bid','名词，指一家公司买下另一家公司。','the rival seeks to acquire ownership.','商业'),C('takeover.s2','控制','The takeover of the club was completed when new owners gained control of its operations.','新业主取得俱乐部运营控制权后，接管工作完成了。','takeover of a company/place/system; military takeover','名词，也指取得某个地方、职位或系统的控制权。','control passes to a new group.','控制')],M('The takeover bid succeeded while the rival company acquired no shares or control.','The takeover bid succeeded when the rival company acquired control of the hotel chain.','收购成功需要取得公司所有权或控制权。','meaning'),[Q(1,'A takeover bid is…','an offer to buy another company','an offer to return a product','a summary of a film','Sense 1 concerns business acquisition.','meaning'),Q(2,'A takeover of a club is complete when…','new owners gain control','the old owners remain in full control','the club holds a symposium','Sense 2 concerns transfer of control.','context'),Q(1,'Which phrase is natural?','a takeover of the company','a takeover the company at','takeoverly of the company','Of introduces the company being acquired or controlled.','grammar'),Q(1,'Takeover is formed from the phrasal verb…','take over','take after','take in','The noun names the act described by take over.','word-formation')]);
P('tale','Tale comes from Old English talu, “story, account,” related to tell; it can be a spoken or written story or an exaggerated, untrue account.',[C('tale.s1','故事','Grandfather told a tale about a fox that outsmarted a greedy farmer.','祖父讲了一个狐狸胜过贪心农夫的故事。','tell/hear a tale; a tale about something','名词，指口头或书面讲述的故事，常含想象情节。','the narrative features an invented fox.','故事'),C('tale.s2','夸张','His tale of catching a shark from the pier did not match the fishing records.','他声称在码头钓到鲨鱼的说法与垂钓记录对不上。','a tall/fish tale; tell a tale','名词，也指夸张或不真实的说法。','the account conflicts with records.','夸张')],M('His tale of catching a shark was accurate and fully confirmed by every fishing record.','His tale of catching a shark was exaggerated and unsupported by the records.','此处tale指夸张、不真实的说法，与记录完全证实相反。','meaning'),[Q(1,'A tale about a clever fox is…','a spoken or written story','a legal rule','a medical device','Sense 1 is a story.','meaning'),Q(2,'An unsupported tale about a shark is…','an exaggerated or possibly untrue account','a scientific synopsis','a guaranteed fact','Sense 2 is the doubtful-account meaning.','context'),Q(1,'Which phrase is natural?','tell a tale about a fox','tell a tale the fox aboutly','a tale tell about of fox','About introduces the story’s subject.','grammar'),Q(1,'Old English talu, ancestor of tale, meant…','story or account','touch','cut','The older word referred to a telling or account.','word-formation')]);
P('talent','Talent came through Old French from Latin talentum and Greek talanton, a unit of weight or money; the ability sense grew from a biblical parable about entrusted sums.',[C('talent.s1','能力','Rosa has a talent for explaining difficult chemistry in plain language.','罗莎擅长用浅显的语言解释复杂的化学知识。','a talent for music/languages; show talent','名词，指把某事做好的自然能力。','her skill is especially strong in explanation.','能力'),C('talent.s2','人才','The studio is looking for new talent to join its animation team.','这家工作室正在寻找加入动画团队的新人才。','young/local talent; recruit talent','名词，也可集合地指有特殊能力的人或一群人才。','the studio seeks skilled people.','人才')],M('Rosa has a talent for chemistry, meaning she is naturally unable to understand or explain it.','Rosa has a talent for chemistry, so she explains difficult ideas clearly.','talent表示能力，不是缺乏理解能力。','meaning'),[Q(1,'A talent for chemistry is…','a natural ability in that subject','a group of people hired together','a written story','Sense 1 is personal ability.','meaning'),Q(2,'A studio seeking new talent is seeking…','people with special abilities','a new system of rules','a medicine tablet','Sense 2 refers to skilled people collectively.','context'),Q(1,'Which phrase is natural?','a talent for languages','a talent at languagesly','talented for a language','For introduces the area of ability.','collocation'),Q(1,'The older Greek talent was a…','unit of weight or money','word for a synapse','kind of tableware','The ability sense developed from the earlier measure of value.','word-formation')]);
P('talented','Talented is formed from talent + -ed; it describes someone born with or displaying a special ability.',C('talented.s1','能力','The school gives talented musicians extra rehearsal time and advanced lessons.','学校为有音乐天赋的学生提供额外排练时间和进阶课程。','a talented artist/student; talented at/in something','形容词，指具有并展现出某种特殊能力。','the students receive instruction matched to high ability.','能力'),M('The talented violinist could not play a note and had no musical ability.','The talented violinist performed difficult passages with skill.','talented指有特殊才能，与完全没有音乐能力相反。','meaning'),[Q(1,'A talented musician is…','someone with a special musical ability','someone with no musical skill','a musical instrument','That is the adjective’s meaning.','meaning'),Q(1,'What support did the school offer?','Extra rehearsals and advanced lessons','A takeover bid','A tablet dose','The context shows the school recognizing ability.','context'),Q(1,'Which phrase is natural?','a talented student in physics','a talent studented in physics','a talentedly student in physics','Talented is an adjective before student.','grammar'),Q(1,'Talented is formed from talent plus…','-ed','-less','-ize','The adjective describes someone endowed with talent.','word-formation')]);
P('talisman','Talisman came through French, in part via Arabic tilsam, from Byzantine Greek telesma, “consecration, ceremony”; it names an object believed to bring luck or a person/thing believed to bring success.',[C('talisman.s1','信物','The runner kept a small brass talisman in her pocket, although she knew it was only a lucky charm.','这名跑者把一枚小黄铜护身符放在口袋里，尽管她知道它只是吉祥物。','carry/wear a talisman; lucky talisman','名词，指人们相信能带来好运或保护平安的物件。','the object is carried for luck.','信物'),C('talisman.s2','象征','The veteran captain became the team’s talisman after leading it to three unexpected victories.','带领球队意外赢得三场比赛后，这位老队长成了球队的幸运象征。','a team’s talisman; talisman of success','名词，也指被认为能给团体带来成功的人或事物。','the captain is associated with the team’s winning run.','象征')],M('The brass talisman was carried as a lucky charm, but its owner believed it brought only bad luck.','The brass talisman was carried because its owner believed it brought good luck.','talisman作为护身符是被相信能带来好运或保护。','meaning'),[Q(1,'A brass talisman is…','an object believed to bring luck or protection','a guaranteed medical treatment','a set of rules','Sense 1 is the charm meaning.','meaning'),Q(2,'Why was the captain the team’s talisman?','The team associated him with its unexpected victories','He was a piece of jewelry','He took over the stadium','Sense 2 applies the word figuratively to a source of success.','context'),Q(1,'Which phrase is natural?','carry a talisman for good luck','carry a talisman to goodly luck','talisman carry for lucky','For introduces the hoped-for benefit.','collocation'),Q(1,'An earlier Arabic source of talisman was…','tilasm','tabula','tassein','The word traveled through Arabic before entering European languages.','word-formation')]);
P('talk','Talk comes from Middle English talken, “speak,” with deeper origins uncertain; it can mean converse, discuss a subject, or a conversation/speech.',[C('talk.s1','交流','We talked for an hour after the lecture and compared our notes.','讲座后我们聊了一个小时，还互相比较了笔记。','talk to/with someone; talk about something','动词，指用语言与别人交流想法。','two people share information in conversation.','交流'),C('talk.s2','讨论','The managers need to talk business before approving the new contract.','经理们需要先谈谈业务，再批准新合同。','talk business; talk about a problem','动词，也指讨论某个话题，常为做决定做准备。','the subject is discussed before approval.','讨论'),C('talk.s3','演讲','She gave a talk on climate adaptation to a room full of city planners.','她向满屋子的城市规划人员作了一场关于气候适应的演讲。','give/deliver a talk; talks between groups','名词，指交谈、面向听众的讲话或正式商谈。','one speaker addresses an audience.','演讲')],M('The managers talked business before the contract by refusing to discuss any business issue.','The managers talked business before deciding whether to approve the contract.','talk business表示讨论业务，拒绝讨论与之相反。','meaning'),[Q(1,'We talked after the lecture means we…','used words to share ideas','wrote a synopsis only','took turns without speaking','Sense 1 is ordinary conversation.','meaning'),Q(2,'Talk business means…','discuss a business subject','give a speech about tableware','follow a van secretly','Sense 2 is discussion for a decision.','context'),Q(3,'She gave a talk on climate means she gave…','a speech to an audience','a set of tactical methods','a talent for music','Sense 3 is the noun meaning speech.','meaning'),Q(1,'Which phrase is natural?','talk with a colleague about the schedule','talk a colleague with about schedulely','talking to the schedule with colleague','With introduces the person in conversation.','collocation')]);
P('talk into','Talk into combines talk with into to mean persuade someone through conversation to do something.',C('talk into.s1','劝说','Her friends talked her into applying for the fellowship after she doubted her experience.','她怀疑自己的经验不足，朋友们便劝她申请这项奖学金。','talk someone into doing something; be talked into a plan','短语动词，指通过交谈说服某人做某事。','the friends persuade her to apply.','劝说'),M('Her friends talked her into applying by insisting that she must not apply under any circumstances.','Her friends talked her into applying by encouraging her and explaining her strengths.','talk someone into是说服对方去做，与劝阻申请相反。','meaning'),[Q(1,'They talked her into applying means they…','persuaded her to apply','forbade her from applying','hired her as a tailor','That is the idiom’s meaning.','meaning'),Q(1,'Why did she hesitate?','She doubted her experience','She had already won the fellowship','She was asked to take over the committee','The context identifies her concern.','context'),Q(1,'Which construction is correct?','talk someone into applying','talk someone to into apply','talk into someone applyingly','Into is followed by a noun or gerund in this idiom.','grammar'),Q(1,'In talk into, into signals…','persuasion leading someone to an action','physical removal from a room','a formal meeting place','The phrase expresses movement toward doing the action.','word-formation')]);
P('talk over','Talk over can mean discuss something carefully before deciding, or speak louder than another sound or person.',[C('talk over.s1','商议','We talked the budget over with the team before choosing a supplier.','选供应商之前，我们和团队把预算仔细谈了一遍。','talk something over with someone; talk over a plan','短语动词，指在决定前与人详细商量。','the group considers the budget together.','商议'),C('talk over.s2','盖过声音','The announcer had to talk over the crowd noise to give the evacuation instructions.','播报员不得不提高声音，盖过人群噪声发布疏散指示。','talk over noise/music; talk over someone','短语动词，也指说得比他人或背景声音更响，使其听不清。','the speaker’s voice must rise above noise.','声音')],M('The announcer talked over the crowd by whispering so softly that nobody could hear the instructions.','The announcer talked over the crowd by speaking loudly enough to be heard.','talk over噪声表示声音盖过背景，不是小声耳语。','meaning'),[Q(1,'They talked the budget over before choosing a supplier means they…','discussed it in detail before deciding','took the budget out of an account','refused to consider it','Sense 1 is deliberation.','meaning'),Q(2,'The announcer talked over the crowd noise means the announcer…','spoke louder than the noise','whispered below the noise','talked about the crowd privately','Sense 2 is speaking above competing sound.','context'),Q(1,'Which phrase is natural?','talk the proposal over with the team','talk the team over the proposal withly','talk over to proposal with team','With introduces the people included in the discussion.','grammar'),Q(1,'In talk over the crowd, over means…','above or louder than','after a relative','into a building','The particle marks sound rising above another sound.','word-formation')]);
P('talks','Talks is the plural of talk; it can mean formal discussions between organizations or a series of speeches to audiences.',[C('talks.s1','谈判','The two governments opened talks on water sharing after months of preparation.','经过数月准备，两国政府就水资源分配开始正式谈判。','hold/open/peace talks; talks between groups','名词复数，指政府、工会或公司围绕共同问题进行的正式商谈。','the parties negotiate a shared issue.','谈判'),C('talks.s2','演讲','The scientist gave talks at six schools during the spring outreach program.','春季科普活动期间，这位科学家在六所学校作了演讲。','give a series of talks; talks on science','名词复数，也指面向听众发表的一系列讲话。','the speaker addresses several audiences.','演讲')],M('The governments opened talks about water sharing, but refused to meet or discuss the issue.','The governments opened talks to discuss water sharing.','talks是正式讨论，完全不见面也不讨论与之矛盾。','meaning'),[Q(1,'Governments opened talks on water sharing means they began…','serious discussions about a shared issue','a series of unrelated school lessons','a public vote only','Sense 1 is the negotiation meaning.','meaning'),Q(2,'The scientist gave talks at six schools means the scientist…','delivered speeches to audiences','negotiated a water treaty','hired six employees','Sense 2 is the speech meaning.','context'),Q(1,'Which collocation is natural?','hold peace talks','hold a peace talksing','talks hold peace at','Talks commonly collocates with hold/open.','collocation'),Q(1,'Talks is the plural form of…','talk','tact','take','It is the regular plural noun.','plural')]);
P('tall','Tall is connected with Old English getæl, “prompt, active”; intermediate senses included “valiant” and “handsome” before the modern height sense, and tall story means an exaggerated account.',[C('tall.s1','身高','At twelve, he was already tall for his age and could reach the top shelf.','他十二岁时就比同龄人高，已经够得到最上层的架子。','tall for one’s age; a tall building/person','形容词，指高度超过一般水平。','the child’s height is above average.','身高'),C('tall.s2','夸张','The fisherman told a tall story about catching a whale in the harbor.','渔夫讲了个离谱的故事，说自己在港口捕到了一头鲸鱼。','a tall story/tale; tell a tall story','形容词，修饰story/tale时表示夸张到令人难以相信。','the claim is implausible.','夸张')],M('The child was tall for his age because he was much shorter than every classmate.','The child was tall for his age because he stood above most classmates.','tall表示身高较高，与明显更矮相反。','meaning'),[Q(1,'Tall for his age means the child…','is higher than average for that age','is shorter than all classmates','tells an unbelievable story','Sense 1 concerns height.','meaning'),Q(2,'A tall story about catching a whale is…','an exaggerated, hard-to-believe account','a very long factual report','a story about someone’s height','Sense 2 is the idiomatic use.','context'),Q(1,'Which phrase is natural?','a tall building','a tallly building','a tale building','Tall is the adjective modifying building.','grammar'),Q(1,'An earlier Old English sense of tall was…','ready or bold','chemical or artificial','a name with similar meaning','The height sense developed later than the recorded earlier sense.','word-formation')]);
})();
